1	/**
2	 * qmd-vector-sidecar HTTP server.
3	 *
4	 * Endpoints:
5	 *   GET  /health   → { ok, provider, model_id, dim, prompt_hash, vector_count, docs, uptime_seconds, db }
6	 *   POST /search   → { hits: SearchHit[] }              body: { query, k?, dedup_by_doc? }
7	 *                  hits is top-k DISTINCT documents by default
8	 *                  (best-scoring chunk per source_doc_id). Pass
9	 *                  dedup_by_doc:false to get raw chunk hits.
10	 *   POST /upsert   → { upserted, unchanged }            body: { chunks: ChunkInput[] }
11	 *   GET  /stats    → { search_count, upsert_count, embed_p95_ms, ... }
12	 *
13	 * Wire shape is intentionally tiny — the dream-memory adapter is the only
14	 * intended client. Search embeds the query via the configured embedder, runs
15	 * a vec0 KNN, returns hits with `distance` + a normalized `score`.
16	 *
17	 * Boot order:
18	 *   1. Read embed config + DB path from env.
19	 *   2. Probe the embedder for dim. If the embedder is not up yet we keep
20	 *      retrying with backoff so the launchd ThrottleInterval can do its job.
21	 *   3. Open the DB. Mismatched index_meta refuses start.
22	 *   4. Listen on $PORT.
23	 */
24	
25	import { createServer, type IncomingMessage, type ServerResponse } from "node:http";
26	import { homedir } from "node:os";
27	import { join } from "node:path";
28	import { mkdir } from "node:fs/promises";
29	import { dirname } from "node:path";
30	
31	import { embedBatch, loadEmbedConfig, probeDim, promptHash, type EmbedConfig } from "./embed.ts";
32	import { openDb, type DbHandle, type ChunkRecord } from "./db.ts";
33	
34	const STARTED_AT = Date.now();
35	const PORT = Number(process.env.PORT ?? 8184);
36	const DB_PATH =
37		process.env.DREAM_VECTOR_DB ?? join(homedir(), ".dream-memory", "external-vectors-mlx.sqlite");
38	const PROVIDER = process.env.DREAM_EMBED_PROVIDER ?? "mlx";
39	const MAX_BODY_BYTES = Number(process.env.SIDECAR_MAX_BODY_BYTES ?? 16 * 1024 * 1024);
40	const SEARCH_DEFAULT_K = Number(process.env.SIDECAR_DEFAULT_K ?? 40);
41	
42	// In-memory counters; surfaced via /stats. Bounded list of latencies for p95.
43	const counters = {
44		search_count: 0,
45		upsert_count: 0,
46		embed_latencies_ms: [] as number[],
47		search_latencies_ms: [] as number[],
48	};
49	
50	function record(latency: number, bucket: "embed" | "search"): void {
51		const arr = bucket === "embed" ? counters.embed_latencies_ms : counters.search_latencies_ms;
52		arr.push(latency);
53		if (arr.length > 1000) arr.splice(0, arr.length - 1000);
54	}
55	
56	function p95(xs: number[]): number {
57		if (xs.length === 0) return 0;
58		const s = [...xs].sort((a, b) => a - b);
59		const k = Math.max(0, Math.min(s.length - 1, Math.floor(0.95 * (s.length - 1))));
60		return Math.round(s[k] ?? 0);
61	}
62	
63	// ---------------------------------------------------------------------------
64	// Boot.
65	
66	async function main(): Promise<void> {
67		const embedCfg = loadEmbedConfig();
68		const expectedPromptHash = promptHash(embedCfg);
69	
70		await mkdir(dirname(DB_PATH), { recursive: true });
71	
72		const dim = await waitForEmbedder(embedCfg);
73		const handle = openDb(DB_PATH, {
74			provider: PROVIDER,
75			model_id: embedCfg.model,
76			dim,
77			prompt_hash: expectedPromptHash,
78		});
79	
80		console.log(
81			`[sidecar] ready: db=${DB_PATH} provider=${PROVIDER} model=${embedCfg.model} dim=${dim} ` +
82				`prompt_hash=${expectedPromptHash} vectors=${handle.stats().vector_count}`,
83		);
84	
85		const server = createServer((req, res) => {
86			handle_request(req, res, handle, embedCfg).catch((err) => {
87				console.error("[sidecar] unhandled:", err);
88				if (!res.headersSent) sendJson(res, 500, { error: String((err as Error).message ?? err) });
89			});
90		});
91	
92		server.listen(PORT, "127.0.0.1", () => {
93			console.log(`[sidecar] listening on http://127.0.0.1:${PORT}`);
94		});
95	
96		const shutdown = (sig: string) => () => {
97			console.log(`[sidecar] ${sig} — closing`);
98			server.close(() => {
99				handle.close();
100				process.exit(0);
101			});
102		};
103		process.on("SIGTERM", shutdown("SIGTERM"));
104		process.on("SIGINT", shutdown("SIGINT"));
105	}
106	
107	async function waitForEmbedder(cfg: EmbedConfig): Promise<number> {
108		let backoff = 500;
109		for (let attempt = 1; attempt <= 30; attempt++) {
110			try {
111				const dim = await probeDim(cfg);
112				if (attempt > 1) console.log(`[sidecar] embedder ready after ${attempt} attempts`);
113				return dim;
114			} catch (err) {
115				console.log(`[sidecar] embedder probe ${attempt} failed: ${(err as Error).message}`);
116				await new Promise((r) => setTimeout(r, backoff));
117				backoff = Math.min(backoff * 1.5, 5_000);
118			}
119		}
120		throw new Error(`embedder at ${cfg.url} did not respond after 30 attempts`);
121	}
122	
123	// ---------------------------------------------------------------------------
124	// Routing.
125	
126	async function handle_request(
127		req: IncomingMessage,
128		res: ServerResponse,
129		handle: DbHandle,
130		embedCfg: EmbedConfig,
131	): Promise<void> {
132		const url = new URL(req.url ?? "/", `http://127.0.0.1:${PORT}`);
133		const route = `${req.method} ${url.pathname}`;
134		switch (route) {
135			case "GET /health":
136				return sendJson(res, 200, healthPayload(handle, embedCfg));
137			case "GET /stats":
138				return sendJson(res, 200, statsPayload(handle));
139			case "POST /search":
140				return handleSearch(req, res, handle, embedCfg);
141			case "POST /upsert":
142				return handleUpsert(req, res, handle, embedCfg);
143			default:
144				return sendJson(res, 404, { error: `no route for ${route}` });
145		}
146	}
147	
148	function healthPayload(handle: DbHandle, embedCfg: EmbedConfig): Record<string, unknown> {
149		const stats = handle.stats();
150		return {
151			ok: true,
152			provider: handle.meta.provider,
153			model_id: handle.meta.model_id,
154			dim: handle.meta.dim,
155			prompt_hash: handle.meta.prompt_hash,
156			vector_count: stats.vector_count,
157			docs: stats.docs,
158			db: {
159				path: stats.db_path,
160				size_bytes: stats.db_size_bytes,
161			},
162			embed_url: embedCfg.url,
163			uptime_seconds: Math.round((Date.now() - STARTED_AT) / 1000),
164		};
165	}
166	
167	function statsPayload(handle: DbHandle): Record<string, unknown> {
168		const stats = handle.stats();
169		return {
170			search_count: counters.search_count,
171			upsert_count: counters.upsert_count,
172			embed_p95_ms: p95(counters.embed_latencies_ms),
173			search_p95_ms: p95(counters.search_latencies_ms),
174			vector_count: stats.vector_count,
175			docs: stats.docs,
176			uptime_seconds: Math.round((Date.now() - STARTED_AT) / 1000),
177		};
178	}
179	
180	async function handleSearch(
181		req: IncomingMessage,
182		res: ServerResponse,
183		handle: DbHandle,
184		embedCfg: EmbedConfig,
185	): Promise<void> {
186		const body = await readJson(req);
187		const query = typeof body.query === "string" ? body.query.trim() : "";
188		const k = Number.isFinite(body.k) ? Math.max(1, Math.min(200, Math.floor(body.k as number))) : SEARCH_DEFAULT_K;
189		const dedupByDoc = body.dedup_by_doc === false ? false : true;
190		if (!query) return sendJson(res, 400, { error: "missing 'query' string" });
191	
192		const t0 = Date.now();
193		const [vec] = await embedBatch([query], "query", embedCfg);
194		record(Date.now() - t0, "embed");
195		if (!vec) return sendJson(res, 502, { error: "embedder returned no vector" });
196	
197		const t1 = Date.now();
198		// Default contract is top-k DISTINCT documents (one entry per
199		// source_doc_id, best-scoring chunk wins). qmd's recall returns
200		// docs, not chunks; matching that contract makes shadow A/B
201		// comparisons meaningful. Over-fetch by 4x to ensure enough
202		// candidates after dedup; cap at the vec0 limit (200).
203		const rawK = dedupByDoc ? Math.min(200, k * 4) : k;
204		const raw = handle.search(vec, rawK);
205		const hits = dedupByDoc ? dedupChunksByDoc(raw, k) : raw;
206		record(Date.now() - t1, "search");
207		counters.search_count++;
208		return sendJson(res, 200, { hits });
209	}
210	
211	/** Keep best-scoring chunk per source_doc_id, preserving distance order,
212	 *  return up to `k` distinct docs. `chunks` MUST come pre-sorted by
213	 *  ascending distance (handle.search guarantees this via ORDER BY). */
214	function dedupChunksByDoc<T extends { source_doc_id: string }>(chunks: T[], k: number): T[] {
215		const seen = new Set<string>();
216		const out: T[] = [];
217		for (const c of chunks) {
218			if (seen.has(c.source_doc_id)) continue;
219			seen.add(c.source_doc_id);
220			out.push(c);
221			if (out.length >= k) break;
222		}
223		return out;
224	}
225	
226	async function handleUpsert(
227		req: IncomingMessage,
228		res: ServerResponse,
229		handle: DbHandle,
230		embedCfg: EmbedConfig,
231	): Promise<void> {
232		const body = await readJson(req);
233		const chunks = Array.isArray(body.chunks) ? (body.chunks as unknown[]) : null;
234		if (!chunks) return sendJson(res, 400, { error: "missing 'chunks' array" });
235	
236		const parsed: ChunkRecord[] = [];
237		for (const raw of chunks) {
238			const chunk = parseChunk(raw);
239			if (!chunk) return sendJson(res, 400, { error: "malformed chunk in body" });
240			parsed.push(chunk);
241		}
242	
243		// Skip work for unchanged chunks before paying the embed cost.
244		const needsEmbed: ChunkRecord[] = [];
245		let unchanged = 0;
246		for (const c of parsed) {
247			if (handle.exists(c.chunk_id, c.chunk_hash)) unchanged++;
248			else needsEmbed.push(c);
249		}
250	
251		let vectors: number[][] = [];
252		if (needsEmbed.length > 0) {
253			const t0 = Date.now();
254			vectors = await embedBatch(needsEmbed.map((c) => c.content), "document", embedCfg);
