/**
 * qmd-vector-sidecar HTTP server.
 *
 * Endpoints:
 *   GET  /health   → { ok, provider, model_id, dim, prompt_hash, vector_count, docs, uptime_seconds, db }
 *   POST /search   → { hits: SearchHit[] }              body: { query, k?, dedup_by_doc? }
 *                  hits is top-k DISTINCT documents by default
 *                  (best-scoring chunk per source_doc_id). Pass
 *                  dedup_by_doc:false to get raw chunk hits.
 *   POST /upsert   → { upserted, unchanged }            body: { chunks: ChunkInput[] }
 *   GET  /stats    → { search_count, upsert_count, embed_p95_ms, ... }
 *
 * Wire shape is intentionally tiny — the dream-memory adapter is the only
 * intended client. Search embeds the query via the configured embedder, runs
 * a vec0 KNN, returns hits with `distance` + a normalized `score`.
 *
 * Boot order:
 *   1. Read embed config + DB path from env.
 *   2. Probe the embedder for dim. If the embedder is not up yet we keep
 *      retrying with backoff so the launchd ThrottleInterval can do its job.
 *   3. Open the DB. Mismatched index_meta refuses start.
 *   4. Listen on $PORT.
 */

import { createServer, type IncomingMessage, type ServerResponse } from "node:http";
import { homedir } from "node:os";
import { join } from "node:path";
import { mkdir } from "node:fs/promises";
import { dirname } from "node:path";

import { embedBatch, loadEmbedConfig, probeDim, promptHash, type EmbedConfig } from "./embed.ts";
import { openDb, type DbHandle, type ChunkRecord } from "./db.ts";

const STARTED_AT = Date.now();
const PORT = Number(process.env.PORT ?? 8184);
const DB_PATH =
	process.env.DREAM_VECTOR_DB ?? join(homedir(), ".dream-memory", "external-vectors-mlx.sqlite");
const PROVIDER = process.env.DREAM_EMBED_PROVIDER ?? "mlx";
const MAX_BODY_BYTES = Number(process.env.SIDECAR_MAX_BODY_BYTES ?? 16 * 1024 * 1024);
const SEARCH_DEFAULT_K = Number(process.env.SIDECAR_DEFAULT_K ?? 40);

// In-memory counters; surfaced via /stats. Bounded list of latencies for p95.
const counters = {
	search_count: 0,
	upsert_count: 0,
	embed_latencies_ms: [] as number[],
	search_latencies_ms: [] as number[],
};

function record(latency: number, bucket: "embed" | "search"): void {
	const arr = bucket === "embed" ? counters.embed_latencies_ms : counters.search_latencies_ms;
	arr.push(latency);
	if (arr.length > 1000) arr.splice(0, arr.length - 1000);
}

function p95(xs: number[]): number {
	if (xs.length === 0) return 0;
	const s = [...xs].sort((a, b) => a - b);
	const k = Math.max(0, Math.min(s.length - 1, Math.floor(0.95 * (s.length - 1))));
	return Math.round(s[k] ?? 0);
}

// ---------------------------------------------------------------------------
// Boot.

async function main(): Promise<void> {
	const embedCfg = loadEmbedConfig();
	const expectedPromptHash = promptHash(embedCfg);

	await mkdir(dirname(DB_PATH), { recursive: true });

	const dim = await waitForEmbedder(embedCfg);
	const handle = openDb(DB_PATH, {
		provider: PROVIDER,
		model_id: embedCfg.model,
		dim,
		prompt_hash: expectedPromptHash,
	});

	console.log(
		`[sidecar] ready: db=${DB_PATH} provider=${PROVIDER} model=${embedCfg.model} dim=${dim} ` +
			`prompt_hash=${expectedPromptHash} vectors=${handle.stats().vector_count}`,
	);

	const server = createServer((req, res) => {
		handle_request(req, res, handle, embedCfg).catch((err) => {
			console.error("[sidecar] unhandled:", err);
			if (!res.headersSent) sendJson(res, 500, { error: String((err as Error).message ?? err) });
		});
	});

	server.listen(PORT, "127.0.0.1", () => {
		console.log(`[sidecar] listening on http://127.0.0.1:${PORT}`);
	});

	const shutdown = (sig: string) => () => {
		console.log(`[sidecar] ${sig} — closing`);
		server.close(() => {
			handle.close();
			process.exit(0);
		});
	};
	process.on("SIGTERM", shutdown("SIGTERM"));
	process.on("SIGINT", shutdown("SIGINT"));
}

async function waitForEmbedder(cfg: EmbedConfig): Promise<number> {
	let backoff = 500;
	for (let attempt = 1; attempt <= 30; attempt++) {
		try {
			const dim = await probeDim(cfg);
			if (attempt > 1) console.log(`[sidecar] embedder ready after ${attempt} attempts`);
			return dim;
		} catch (err) {
			console.log(`[sidecar] embedder probe ${attempt} failed: ${(err as Error).message}`);
			await new Promise((r) => setTimeout(r, backoff));
			backoff = Math.min(backoff * 1.5, 5_000);
		}
	}
	throw new Error(`embedder at ${cfg.url} did not respond after 30 attempts`);
}

// ---------------------------------------------------------------------------
// Routing.

async function handle_request(
	req: IncomingMessage,
	res: ServerResponse,
	handle: DbHandle,
	embedCfg: EmbedConfig,
): Promise<void> {
	const url = new URL(req.url ?? "/", `http://127.0.0.1:${PORT}`);
	const route = `${req.method} ${url.pathname}`;
	switch (route) {
		case "GET /health":
			return sendJson(res, 200, healthPayload(handle, embedCfg));
		case "GET /stats":
			return sendJson(res, 200, statsPayload(handle));
		case "POST /search":
			return handleSearch(req, res, handle, embedCfg);
		case "POST /upsert":
			return handleUpsert(req, res, handle, embedCfg);
		default:
			return sendJson(res, 404, { error: `no route for ${route}` });
	}
}

function healthPayload(handle: DbHandle, embedCfg: EmbedConfig): Record<string, unknown> {
	const stats = handle.stats();
	return {
		ok: true,
		provider: handle.meta.provider,
		model_id: handle.meta.model_id,
		dim: handle.meta.dim,
		prompt_hash: handle.meta.prompt_hash,
		vector_count: stats.vector_count,
		docs: stats.docs,
		db: {
			path: stats.db_path,
			size_bytes: stats.db_size_bytes,
		},
		embed_url: embedCfg.url,
		uptime_seconds: Math.round((Date.now() - STARTED_AT) / 1000),
	};
}

function statsPayload(handle: DbHandle): Record<string, unknown> {
	const stats = handle.stats();
	return {
		search_count: counters.search_count,
		upsert_count: counters.upsert_count,
		embed_p95_ms: p95(counters.embed_latencies_ms),
		search_p95_ms: p95(counters.search_latencies_ms),
		vector_count: stats.vector_count,
		docs: stats.docs,
		uptime_seconds: Math.round((Date.now() - STARTED_AT) / 1000),
	};
}

async function handleSearch(
	req: IncomingMessage,
	res: ServerResponse,
	handle: DbHandle,
	embedCfg: EmbedConfig,
): Promise<void> {
	const body = await readJson(req);
	const query = typeof body.query === "string" ? body.query.trim() : "";
	const k = Number.isFinite(body.k) ? Math.max(1, Math.min(200, Math.floor(body.k as number))) : SEARCH_DEFAULT_K;
	const dedupByDoc = body.dedup_by_doc === false ? false : true;
	if (!query) return sendJson(res, 400, { error: "missing 'query' string" });

	const t0 = Date.now();
	const [vec] = await embedBatch([query], "query", embedCfg);
	record(Date.now() - t0, "embed");
	if (!vec) return sendJson(res, 502, { error: "embedder returned no vector" });

	const t1 = Date.now();
	// Default contract is top-k DISTINCT documents (one entry per
	// source_doc_id, best-scoring chunk wins). qmd's recall returns
	// docs, not chunks; matching that contract makes shadow A/B
	// comparisons meaningful. Over-fetch by 4x to ensure enough
	// candidates after dedup; cap at the vec0 limit (200).
	const rawK = dedupByDoc ? Math.min(200, k * 4) : k;
	const raw = handle.search(vec, rawK);
	const hits = dedupByDoc ? dedupChunksByDoc(raw, k) : raw;
	record(Date.now() - t1, "search");
	counters.search_count++;
	return sendJson(res, 200, { hits });
}

/** Keep best-scoring chunk per source_doc_id, preserving distance order,
 *  return up to `k` distinct docs. `chunks` MUST come pre-sorted by
 *  ascending distance (handle.search guarantees this via ORDER BY). */
function dedupChunksByDoc<T extends { source_doc_id: string }>(chunks: T[], k: number): T[] {
	const seen = new Set<string>();
	const out: T[] = [];
	for (const c of chunks) {
		if (seen.has(c.source_doc_id)) continue;
		seen.add(c.source_doc_id);
		out.push(c);
		if (out.length >= k) break;
	}
	return out;
}

async function handleUpsert(
	req: IncomingMessage,
	res: ServerResponse,
	handle: DbHandle,
	embedCfg: EmbedConfig,
): Promise<void> {
	const body = await readJson(req);
	const chunks = Array.isArray(body.chunks) ? (body.chunks as unknown[]) : null;
	if (!chunks) return sendJson(res, 400, { error: "missing 'chunks' array" });

	const parsed: ChunkRecord[] = [];
	for (const raw of chunks) {
		const chunk = parseChunk(raw);
		if (!chunk) return sendJson(res, 400, { error: "malformed chunk in body" });
		parsed.push(chunk);
	}

	// Skip work for unchanged chunks before paying the embed cost.
	const needsEmbed: ChunkRecord[] = [];
	let unchanged = 0;
	for (const c of parsed) {
		if (handle.exists(c.chunk_id, c.chunk_hash)) unchanged++;
		else needsEmbed.push(c);
	}

	let vectors: number[][] = [];
	if (needsEmbed.length > 0) {
		const t0 = Date.now();
		vectors = await embedBatch(needsEmbed.map((c) => c.content), "document", embedCfg);
		record(Date.now() - t0, "embed");
		if (vectors.length !== needsEmbed.length) {
			return sendJson(res, 502, {
				error: `embedder returned ${vectors.length} vectors for ${needsEmbed.length} chunks`,
			});
		}
	}

	const rows = needsEmbed.map((chunk, i) => ({ chunk, vector: vectors[i] as number[] }));
	const result = handle.upsert(rows);
	counters.upsert_count += result.upserted;
	return sendJson(res, 200, { upserted: result.upserted, unchanged: unchanged + result.unchanged });
}

function parseChunk(raw: unknown): ChunkRecord | null {
	if (!raw || typeof raw !== "object") return null;
	const r = raw as Record<string, unknown>;
	if (typeof r.chunk_id !== "string" || !r.chunk_id) return null;
	if (typeof r.source_doc_id !== "string" || !r.source_doc_id) return null;
	if (typeof r.path !== "string" || !r.path) return null;
	if (typeof r.content !== "string" || !r.content) return null;
	if (typeof r.chunk_hash !== "string" || !r.chunk_hash) return null;
	return {
		chunk_id: r.chunk_id,
		source_doc_id: r.source_doc_id,
		path: r.path,
		title: typeof r.title === "string" ? r.title : null,
		content: r.content,
		chunk_hash: r.chunk_hash,
	};
}

// ---------------------------------------------------------------------------
// Plumbing.

async function readJson(req: IncomingMessage): Promise<Record<string, unknown>> {
	const chunks: Buffer[] = [];
	let total = 0;
	for await (const chunk of req) {
		const buf = chunk as Buffer;
		total += buf.length;
		if (total > MAX_BODY_BYTES) throw new Error(`body too large (>${MAX_BODY_BYTES} bytes)`);
		chunks.push(buf);
	}
	const text = Buffer.concat(chunks).toString("utf8");
	if (!text) return {};
	try {
		const parsed = JSON.parse(text);
		if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) return parsed;
		return { _root: parsed };
	} catch (err) {
		throw new Error(`invalid JSON: ${(err as Error).message}`);
	}
}

function sendJson(res: ServerResponse, status: number, body: unknown): void {
	const payload = JSON.stringify(body);
	res.writeHead(status, {
		"Content-Type": "application/json",
		"Content-Length": Buffer.byteLength(payload),
	});
	res.end(payload);
}

main().catch((err) => {
	console.error("[sidecar] fatal:", err);
	process.exit(1);
});

