61	export function applyPatchSet(currentWiki: WikiFile[], patchSet: PatchSet): PatchApplyResult {
62		const audit: PatchAuditEntry[] = [];
63		const errors: PatchApplyError[] = [];
64		const parsed = currentWiki.map(parseWikiFile);
65		const byPath = new Map(parsed.map((file) => [file.path, file]));
66		const byPermalink = new Map<string, ParsedWikiFile>();
67		for (const file of parsed) {
68			const permalink = file.frontmatter.permalink;
69			if (typeof permalink === "string" && permalink.length > 0) byPermalink.set(permalink, file);
70		}
71	
72		const planned: PlannedPatch[] = [];
73		for (const patch of patchSet.patches) {
74			const resolved = resolveTarget(patch, byPath, byPermalink);
75			if ("error" in resolved) {
76				const message = resolved.error ?? "target resolution failed";
77				errors.push({ patchId: patch.id, message });
78				audit.push({ patchId: patch.id, action: "rejected", detail: message });
79				continue;
80			}
81			planned.push({ patch, path: resolved.path, ...(resolved.existing ? { existing: resolved.existing } : {}) });
82		}
83	
84		for (const plan of planned) {
85			const err = validatePlan(plan);
86			if (err) {
87				errors.push({ patchId: plan.patch.id, message: err });
88				audit.push({ patchId: plan.patch.id, action: "rejected", path: plan.path, detail: err });
89			}
90		}
91	
92		if (errors.length > 0) return { newWiki: currentWiki, errors, audit };
93	
94		const next = new Map(parsed.map((file) => [file.path, { ...file }]));
95		for (const plan of planned) {
96			const before = next.get(plan.path);
97			const result = applyOne(before, plan.patch, plan.path);
98			next.set(plan.path, parseWikiFile({ path: plan.path, content: result.content }));
99			audit.push({ patchId: plan.patch.id, action: result.action, path: plan.path, ...(result.detail ? { detail: result.detail } : {}) });
100		}
101	
102		const originalOrder = currentWiki.map((f) => f.path);
103		const allPaths = [...originalOrder, ...[...next.keys()].filter((p) => !originalOrder.includes(p)).sort()];
104		return {
105			newWiki: allPaths.map((path) => ({ path, content: next.get(path)!.content })),
106			errors,
107			audit,
108		};
109	}
110	
111	function resolveTarget(
112		patch: DreamPatch,
113		byPath: Map<string, ParsedWikiFile>,
114		byPermalink: Map<string, ParsedWikiFile>,
115	): { path: string; existing?: ParsedWikiFile; error?: undefined } | { error: string } {
116		const pathFile = patch.target.path ? byPath.get(patch.target.path) : undefined;
117		const permalinkFile = patch.target.permalink ? byPermalink.get(patch.target.permalink) : undefined;
118		if (pathFile && permalinkFile && pathFile.path !== permalinkFile.path) {
119			return { error: `target path and permalink resolve to different files (${pathFile.path} vs ${permalinkFile.path})` };
120		}
121		const existing = pathFile ?? permalinkFile;
122		const path = existing?.path ?? patch.target.path;
123		if (!path) return { error: "target path required when permalink does not resolve" };
124		return existing ? { path, existing } : { path };
