127	function validatePlan(plan: PlannedPatch): string | null {
128		if (!isSafeRelativePath(plan.path)) return `unsafe path: ${plan.path}`;
129		if (!plan.existing && plan.patch.op !== "replace_file") return `${plan.patch.op} target does not exist; use replace_file for new files`;
130		if (plan.existing && plan.patch.op === "replace_file" && !plan.patch.allow_overwrite) return "replace_file on existing file requires allow_overwrite";
131		if (plan.patch.op === "upsert_section" || plan.patch.op === "append_to_section") {
