191	function parseYamlish(text: string): Record<string, unknown> {
192		const out: Record<string, unknown> = {};
193		const lines = text.split("\n");
194		for (let i = 0; i < lines.length; i++) {
195			const line = lines[i] ?? "";
196			const m = /^(\w[\w_]*):(?:\s*(.*))?$/.exec(line);
197			if (!m) continue;
198			const key = m[1]!;
199			const raw = m[2] ?? "";
200			if (raw === "") {
201				const arr: string[] = [];
202				while (i + 1 < lines.length && /^\s+-\s+/.test(lines[i + 1] ?? "")) {
203					i += 1;
204					arr.push(parseScalar((lines[i] ?? "").replace(/^\s+-\s+/, "")) as string);
205				}
206				out[key] = arr;
207			} else {
208				out[key] = parseScalar(raw);
209			}
210		}
211		return out;
212	}
213	
214	function parseScalar(raw: string): unknown {
215		try { return JSON.parse(raw); } catch { /* yaml-ish bare scalar */ }
216		if (raw === "true") return true;
217		if (raw === "false") return false;
218		const n = Number(raw);
219		if (raw !== "" && Number.isFinite(n)) return n;
220		return raw;
221	}
222	
223	function serialise(frontmatter: Record<string, unknown>, body: string): string {
224		const lines = ["---"];
225		const keys = [
226			...FRONTMATTER_ORDER.filter((key) => Object.prototype.hasOwnProperty.call(frontmatter, key)),
227			...Object.keys(frontmatter).filter((key) => !FRONTMATTER_ORDER.includes(key)).sort(),
228		];
229		for (const key of keys) {
230			const value = frontmatter[key];
231			if (value === undefined || value === null) continue;
232			if (Array.isArray(value)) {
233				lines.push(`${key}:`);
234				for (const item of value) lines.push(`  - ${JSON.stringify(item)}`);
235			} else if (typeof value === "string") {
236				lines.push(`${key}: ${JSON.stringify(value)}`);
237			} else {
238				lines.push(`${key}: ${JSON.stringify(value)}`);
239			}
240		}
241		lines.push("---", "");
242		return `${lines.join("\n")}${body.replace(/\s*$/, "")}\n`;
243	}
244	
245	function normalizeHeading(heading: string): string {
246		return heading.trim().replace(/\s+/g, " ");
247	}
248	
249	function findH2Sections(body: string, heading: string): Array<{ start: number; contentStart: number; end: number }> {
250		const normalized = normalizeHeading(heading);
251		const matches: Array<{ start: number; contentStart: number; end: number }> = [];
252		const re = /^##\s+(.+)$/gm;
253		let match: RegExpExecArray | null;
254		while ((match = re.exec(body))) {
255			const foundHeading = match[1] ?? "";
256			if (normalizeHeading(foundHeading) !== normalized) continue;
257			const start = match.index;
258			const contentStart = re.lastIndex;
259			const next = /^##\s+.+$/gm;
260			next.lastIndex = contentStart;
261			const nextMatch = next.exec(body);
262			const end = nextMatch ? nextMatch.index : body.length;
263			matches.push({ start, contentStart, end });
264		}
265		return matches;
266	}
267	
268	function countH2(body: string, heading: string): number {
269		return findH2Sections(body, heading).length;
270	}
271	
272	function upsertSection(body: string, heading: string, content: string): string {
273		const section = `## ${normalizeHeading(heading)}\n\n${content.trim()}\n`;
274		const matches = findH2Sections(body, heading);
275		if (matches.length === 0) return `${body.replace(/\s*$/, "")}\n\n${section}`.replace(/^\n+/, "");
276		const m = matches[0]!;
277		return `${body.slice(0, m.start).replace(/\s*$/, "")}\n\n${section}${body.slice(m.end).replace(/^\s*/, "\n")}`.replace(/^\n+/, "").replace(/\s*$/, "");
278	}
279	
280	function appendToSection(body: string, heading: string, content: string, dedupe: "block" | "line" | "none"): { body: string; appended: number } {
281		let base = body;
282		let matches = findH2Sections(base, heading);
283		if (matches.length === 0) {
284			base = upsertSection(base, heading, "");
285			matches = findH2Sections(base, heading);
286		}
287		const m = matches[0]!;
288		const existing = base.slice(m.contentStart, m.end).trim();
289		const additions = splitAdditions(content, dedupe);
290		const existingSet = new Set(splitAdditions(existing, dedupe).map(normalizeBlock));
291		const toAdd = dedupe === "none" ? additions : additions.filter((block) => !existingSet.has(normalizeBlock(block)));
292		if (toAdd.length === 0) return { body: base.replace(/\s*$/, ""), appended: 0 };
293		const newSectionBody = [existing, ...toAdd].filter(Boolean).join("\n\n");
294		const section = `## ${normalizeHeading(heading)}\n\n${newSectionBody}\n`;
295		const nextBody = `${base.slice(0, m.start).replace(/\s*$/, "")}\n\n${section}${base.slice(m.end).replace(/^\s*/, "\n")}`.replace(/^\n+/, "").replace(/\s*$/, "");
296		return { body: nextBody, appended: toAdd.length };
297	}
298	
299	function splitAdditions(content: string, dedupe: "block" | "line" | "none"): string[] {
300		const trimmed = content.trim();
301		if (!trimmed) return [];
302		if (dedupe === "line") return trimmed.split("\n").map((line) => line.trim()).filter(Boolean);
303		return trimmed.split(/\n{2,}/).map((block) => block.trim()).filter(Boolean);
304	}
305	
306	function normalizeBlock(block: string): string {
307		return block.trim().replace(/\s+/g, " ");
308	}
309	
310	function isSafeRelativePath(path: string): boolean {
311		return !path.startsWith("/") && !path.split(/[\\/]+/).includes("..");
312	}
