import type { DreamFile } from "./schema.ts";
import type { DreamPatch, PatchSet } from "./patch-schema.ts";

export type WikiFile = {
	path: string;
	content: string;
};

export type PatchApplyError = {
	patchId: string;
	message: string;
};

export type PatchAuditEntry = {
	patchId: string;
	action: "created_file" | "replaced_file" | "upserted_section" | "appended_blocks" | "noop" | "rejected";
	path?: string;
	detail?: string;
};

export type PatchApplyResult = {
	newWiki: WikiFile[];
	errors: PatchApplyError[];
	audit: PatchAuditEntry[];
};

export function parseAppliedWikiFile(file: WikiFile): DreamFile {
	const parsed = parseWikiFile(file);
	return {
		path: file.path,
		frontmatter: parsed.frontmatter as DreamFile["frontmatter"],
		markdown: parsed.body,
	};
}

const FRONTMATTER_ORDER = [
	"source_event_ids",
	"source_event_ids_truncated_at",
	"title",
	"type",
	"permalink",
	"scope",
	"project",
	"last_dreamed_at",
	"confidence",
	"supersedes",
];
const PROVENANCE_CAP = 200;

type ParsedWikiFile = WikiFile & {
	frontmatter: Record<string, unknown>;
	body: string;
};

type PlannedPatch = {
	patch: DreamPatch;
	path: string;
	existing?: ParsedWikiFile;
};

export function applyPatchSet(currentWiki: WikiFile[], patchSet: PatchSet): PatchApplyResult {
	const audit: PatchAuditEntry[] = [];
	const errors: PatchApplyError[] = [];
	const parsed = currentWiki.map(parseWikiFile);
	const byPath = new Map(parsed.map((file) => [file.path, file]));
	const byPermalink = new Map<string, ParsedWikiFile>();
	for (const file of parsed) {
		const permalink = file.frontmatter.permalink;
		if (typeof permalink === "string" && permalink.length > 0) byPermalink.set(permalink, file);
	}

	const planned: PlannedPatch[] = [];
	for (const patch of patchSet.patches) {
		const resolved = resolveTarget(patch, byPath, byPermalink);
		if ("error" in resolved) {
			const message = resolved.error ?? "target resolution failed";
			errors.push({ patchId: patch.id, message });
			audit.push({ patchId: patch.id, action: "rejected", detail: message });
			continue;
		}
		planned.push({ patch, path: resolved.path, ...(resolved.existing ? { existing: resolved.existing } : {}) });
	}

	for (const plan of planned) {
		const err = validatePlan(plan);
		if (err) {
			errors.push({ patchId: plan.patch.id, message: err });
			audit.push({ patchId: plan.patch.id, action: "rejected", path: plan.path, detail: err });
		}
	}

	if (errors.length > 0) return { newWiki: currentWiki, errors, audit };

	const next = new Map(parsed.map((file) => [file.path, { ...file }]));
	for (const plan of planned) {
		const before = next.get(plan.path);
		const result = applyOne(before, plan.patch, plan.path);
		next.set(plan.path, parseWikiFile({ path: plan.path, content: result.content }));
		audit.push({ patchId: plan.patch.id, action: result.action, path: plan.path, ...(result.detail ? { detail: result.detail } : {}) });
	}

	const originalOrder = currentWiki.map((f) => f.path);
	const allPaths = [...originalOrder, ...[...next.keys()].filter((p) => !originalOrder.includes(p)).sort()];
	return {
		newWiki: allPaths.map((path) => ({ path, content: next.get(path)!.content })),
		errors,
		audit,
	};
}

function resolveTarget(
	patch: DreamPatch,
	byPath: Map<string, ParsedWikiFile>,
	byPermalink: Map<string, ParsedWikiFile>,
): { path: string; existing?: ParsedWikiFile; error?: undefined } | { error: string } {
	const pathFile = patch.target.path ? byPath.get(patch.target.path) : undefined;
	const permalinkFile = patch.target.permalink ? byPermalink.get(patch.target.permalink) : undefined;
	if (pathFile && permalinkFile && pathFile.path !== permalinkFile.path) {
		return { error: `target path and permalink resolve to different files (${pathFile.path} vs ${permalinkFile.path})` };
	}
	const existing = pathFile ?? permalinkFile;
	const path = existing?.path ?? patch.target.path;
	if (!path) return { error: "target path required when permalink does not resolve" };
	return existing ? { path, existing } : { path };
}

function validatePlan(plan: PlannedPatch): string | null {
	if (!isSafeRelativePath(plan.path)) return `unsafe path: ${plan.path}`;
	if (!plan.existing && plan.patch.op !== "replace_file") return `${plan.patch.op} target does not exist; use replace_file for new files`;
	if (plan.existing && plan.patch.op === "replace_file" && !plan.patch.allow_overwrite) return "replace_file on existing file requires allow_overwrite";
	if (plan.patch.op === "upsert_section" || plan.patch.op === "append_to_section") {
		const count = countH2(plan.existing!.body, plan.patch.heading);
		if (count > 1) return `ambiguous duplicate H2 heading: ${plan.patch.heading}`;
	}
	return null;
}

function applyOne(existing: ParsedWikiFile | undefined, patch: DreamPatch, path: string): { content: string; action: PatchAuditEntry["action"]; detail?: string } {
	if (patch.op === "replace_file") {
		const frontmatter = mergeProvenance({ ...patch.frontmatter }, patch.source_event_ids);
		const content = serialise(frontmatter, patch.markdown);
		if (existing?.content === content) return { content, action: "noop" };
		return { content, action: existing ? "replaced_file" : "created_file" };
	}

	const existingFile = existing!;
	const frontmatter = mergeSectionFrontmatter(existingFile.frontmatter, patch);
	if (patch.op === "upsert_section") {
		const body = upsertSection(existingFile.body, patch.heading, patch.content);
		const content = serialise(frontmatter, body);
		return { content, action: content === existingFile.content ? "noop" : "upserted_section" };
	}

	const { body, appended } = appendToSection(existingFile.body, patch.heading, patch.content, patch.dedupe);
	const content = serialise(frontmatter, body);
	return { content, action: appended === 0 && content === existingFile.content ? "noop" : "appended_blocks", detail: `${appended} block(s)` };
}

function mergeSectionFrontmatter(existing: Record<string, unknown>, patch: Extract<DreamPatch, { op: "upsert_section" | "append_to_section" }>): Record<string, unknown> {
	const allowed = new Set(["title", "type", "last_dreamed_at", "confidence", "supersedes"]);
	const next: Record<string, unknown> = { ...existing };
	if (patch.op === "upsert_section" && patch.frontmatter) {
		for (const [key, value] of Object.entries(patch.frontmatter)) {
			if (value !== undefined && allowed.has(key)) next[key] = value;
		}
	}
	return mergeProvenance(next, patch.source_event_ids);
}

function mergeProvenance(frontmatter: Record<string, unknown>, ids: string[]): Record<string, unknown> {
	const existing = Array.isArray(frontmatter.source_event_ids) ? frontmatter.source_event_ids.filter((id): id is string => typeof id === "string") : [];
	const union = [...existing];
	for (const id of ids) if (!union.includes(id)) union.push(id);
	if (union.length > PROVENANCE_CAP) {
		const retained = union.slice(-PROVENANCE_CAP);
		frontmatter.source_event_ids = retained;
		frontmatter.source_event_ids_truncated_at = retained[0];
	} else {
		frontmatter.source_event_ids = union;
	}
	return frontmatter;
}

function parseWikiFile(file: WikiFile): ParsedWikiFile {
	const match = /^---\n([\s\S]*?)\n---\n?([\s\S]*)$/.exec(file.content);
	if (!match) return { ...file, frontmatter: {}, body: file.content.replace(/\s*$/, "") };
	const [, frontmatterText = "", bodyText = ""] = match;
	return { ...file, frontmatter: parseYamlish(frontmatterText), body: bodyText.replace(/\s*$/, "") };
}

function parseYamlish(text: string): Record<string, unknown> {
	const out: Record<string, unknown> = {};
	const lines = text.split("\n");
	for (let i = 0; i < lines.length; i++) {
		const line = lines[i] ?? "";
		const m = /^(\w[\w_]*):(?:\s*(.*))?$/.exec(line);
		if (!m) continue;
		const key = m[1]!;
		const raw = m[2] ?? "";
		if (raw === "") {
			const arr: string[] = [];
			while (i + 1 < lines.length && /^\s+-\s+/.test(lines[i + 1] ?? "")) {
				i += 1;
				arr.push(parseScalar((lines[i] ?? "").replace(/^\s+-\s+/, "")) as string);
			}
			out[key] = arr;
		} else {
			out[key] = parseScalar(raw);
		}
	}
	return out;
}

function parseScalar(raw: string): unknown {
	try { return JSON.parse(raw); } catch { /* yaml-ish bare scalar */ }
	if (raw === "true") return true;
	if (raw === "false") return false;
	const n = Number(raw);
	if (raw !== "" && Number.isFinite(n)) return n;
	return raw;
}

function serialise(frontmatter: Record<string, unknown>, body: string): string {
	const lines = ["---"];
	const keys = [
		...FRONTMATTER_ORDER.filter((key) => Object.prototype.hasOwnProperty.call(frontmatter, key)),
		...Object.keys(frontmatter).filter((key) => !FRONTMATTER_ORDER.includes(key)).sort(),
	];
	for (const key of keys) {
		const value = frontmatter[key];
		if (value === undefined || value === null) continue;
		if (Array.isArray(value)) {
			lines.push(`${key}:`);
			for (const item of value) lines.push(`  - ${JSON.stringify(item)}`);
		} else if (typeof value === "string") {
			lines.push(`${key}: ${JSON.stringify(value)}`);
		} else {
			lines.push(`${key}: ${JSON.stringify(value)}`);
		}
	}
	lines.push("---", "");
	return `${lines.join("\n")}${body.replace(/\s*$/, "")}\n`;
}

function normalizeHeading(heading: string): string {
	return heading.trim().replace(/\s+/g, " ");
}

function findH2Sections(body: string, heading: string): Array<{ start: number; contentStart: number; end: number }> {
	const normalized = normalizeHeading(heading);
	const matches: Array<{ start: number; contentStart: number; end: number }> = [];
	const re = /^##\s+(.+)$/gm;
	let match: RegExpExecArray | null;
	while ((match = re.exec(body))) {
		const foundHeading = match[1] ?? "";
		if (normalizeHeading(foundHeading) !== normalized) continue;
		const start = match.index;
		const contentStart = re.lastIndex;
		const next = /^##\s+.+$/gm;
		next.lastIndex = contentStart;
		const nextMatch = next.exec(body);
		const end = nextMatch ? nextMatch.index : body.length;
		matches.push({ start, contentStart, end });
	}
	return matches;
}

function countH2(body: string, heading: string): number {
	return findH2Sections(body, heading).length;
}

function upsertSection(body: string, heading: string, content: string): string {
	const section = `## ${normalizeHeading(heading)}\n\n${content.trim()}\n`;
	const matches = findH2Sections(body, heading);
	if (matches.length === 0) return `${body.replace(/\s*$/, "")}\n\n${section}`.replace(/^\n+/, "");
	const m = matches[0]!;
	return `${body.slice(0, m.start).replace(/\s*$/, "")}\n\n${section}${body.slice(m.end).replace(/^\s*/, "\n")}`.replace(/^\n+/, "").replace(/\s*$/, "");
}

function appendToSection(body: string, heading: string, content: string, dedupe: "block" | "line" | "none"): { body: string; appended: number } {
	let base = body;
	let matches = findH2Sections(base, heading);
	if (matches.length === 0) {
		base = upsertSection(base, heading, "");
		matches = findH2Sections(base, heading);
	}
	const m = matches[0]!;
	const existing = base.slice(m.contentStart, m.end).trim();
	const additions = splitAdditions(content, dedupe);
	const existingSet = new Set(splitAdditions(existing, dedupe).map(normalizeBlock));
	const toAdd = dedupe === "none" ? additions : additions.filter((block) => !existingSet.has(normalizeBlock(block)));
	if (toAdd.length === 0) return { body: base.replace(/\s*$/, ""), appended: 0 };
	const newSectionBody = [existing, ...toAdd].filter(Boolean).join("\n\n");
	const section = `## ${normalizeHeading(heading)}\n\n${newSectionBody}\n`;
	const nextBody = `${base.slice(0, m.start).replace(/\s*$/, "")}\n\n${section}${base.slice(m.end).replace(/^\s*/, "\n")}`.replace(/^\n+/, "").replace(/\s*$/, "");
	return { body: nextBody, appended: toAdd.length };
}

function splitAdditions(content: string, dedupe: "block" | "line" | "none"): string[] {
	const trimmed = content.trim();
	if (!trimmed) return [];
	if (dedupe === "line") return trimmed.split("\n").map((line) => line.trim()).filter(Boolean);
	return trimmed.split(/\n{2,}/).map((block) => block.trim()).filter(Boolean);
}

function normalizeBlock(block: string): string {
	return block.trim().replace(/\s+/g, " ");
}

function isSafeRelativePath(path: string): boolean {
	return !path.startsWith("/") && !path.split(/[\\/]+/).includes("..");
}

