import { z } from "zod";

import { FrontmatterSchema } from "./schema.ts";

const relativeMemoryPath = z.string().min(1).refine((path) => {
	return !path.startsWith("/") && !path.split(/[\\/]+/).includes("..");
}, "path must be relative and stay under memory/");

export const PatchTargetSchema = z.object({
	path: relativeMemoryPath.optional(),
	permalink: z.string().min(1).optional(),
}).refine((target) => target.path || target.permalink, "path or permalink required");
export type PatchTarget = z.infer<typeof PatchTargetSchema>;

const HeadingSchema = z.string().min(1)
	.refine((heading) => !heading.includes("\n") && !heading.includes("\r"), "heading must be one line")
	.refine((heading) => !heading.trimStart().startsWith("#"), "heading must omit leading # markers")
	.transform((heading) => heading.trim());

const SectionContentSchema = z.string().min(1)
	.refine((content) => !/^##\s+/m.test(content), "content must not contain H2 headings");

const PatchBaseSchema = z.object({
	id: z.string().min(1),
	source_event_ids: z.array(z.string().min(1)).min(1),
	rationale: z.string().min(1).optional(),
});

export const ReplaceFilePatchSchema = PatchBaseSchema.extend({
	op: z.literal("replace_file"),
	target: PatchTargetSchema,
	frontmatter: FrontmatterSchema,
	markdown: z.string().min(1),
	allow_overwrite: z.boolean().default(false),
});

export const UpsertSectionPatchSchema = PatchBaseSchema.extend({
	op: z.literal("upsert_section"),
	target: PatchTargetSchema,
	heading: HeadingSchema,
	content: SectionContentSchema,
	frontmatter: FrontmatterSchema.partial().optional(),
});

export const AppendToSectionPatchSchema = PatchBaseSchema.extend({
	op: z.literal("append_to_section"),
	target: PatchTargetSchema,
	heading: HeadingSchema,
	content: z.string().min(1),
	dedupe: z.enum(["block", "line", "none"]).default("block"),
});

export const DreamPatchSchema = z.discriminatedUnion("op", [
	ReplaceFilePatchSchema,
	UpsertSectionPatchSchema,
	AppendToSectionPatchSchema,
]);
export type DreamPatch = z.infer<typeof DreamPatchSchema>;

export const PatchSetSchema = z.object({
	patches: z.array(DreamPatchSchema).min(1),
	consumed_event_ids: z.array(z.string().min(1)).min(1),
});
export type PatchSet = z.infer<typeof PatchSetSchema>;

