import { describe, expect, it } from "vitest";

import { applyPatchSet, type WikiFile } from "../src/dream/patch-applier.ts";
import { PatchSetSchema, type PatchSet } from "../src/dream/patch-schema.ts";

const fm = (ids = ["e1"], extra = "") => `---
source_event_ids:
${ids.map((id) => `  - "${id}"`).join("\n")}
title: "Prefs"
type: "note"
permalink: "profile/preferences"
scope: "profile"
last_dreamed_at: "2026-05-12T00:00:00.000Z"
confidence: 0.9
${extra}---
`;

const baseFile = (body = "# Prefs\n\nIntro.\n\n## Existing\n\nOld text.\n\n## Keep\n\nHuman text.\n"): WikiFile => ({
	path: "profile/preferences.md",
	content: fm() + body,
});

const basePatch = {
	id: "p1",
	source_event_ids: ["e2"],
	target: { path: "profile/preferences.md" },
};

function patchSet(patches: unknown[]): PatchSet {
	return { patches, consumed_event_ids: ["e2"] } as PatchSet;
}

describe("PatchSetSchema", () => {
	it("accepts the three patch operations", () => {
		const parsed = PatchSetSchema.safeParse(patchSet([
			{ ...basePatch, op: "upsert_section", heading: "Summary", content: "New summary." },
			{ ...basePatch, id: "p2", op: "append_to_section", heading: "Recall triggers", content: "- remember prefs" },
			{
				...basePatch,
				id: "p3",
				op: "replace_file",
				target: { path: "profile/new.md" },
				frontmatter: {
					source_event_ids: ["e2"], title: "New", type: "note", permalink: "profile/new", scope: "profile",
					last_dreamed_at: "2026-05-12T00:00:00.000Z", confidence: 0.8,
				},
				markdown: "# New\n\nBody.",
			},
		]));
		expect(parsed.success).toBe(true);
	});

	it("rejects unsafe paths and malformed headings", () => {
		expect(PatchSetSchema.safeParse(patchSet([{ ...basePatch, target: { path: "../x.md" }, op: "upsert_section", heading: "Ok", content: "Body" }])).success).toBe(false);
		expect(PatchSetSchema.safeParse(patchSet([{ ...basePatch, op: "upsert_section", heading: "## Bad", content: "Body" }])).success).toBe(false);
		expect(PatchSetSchema.safeParse(patchSet([{ ...basePatch, op: "upsert_section", heading: "Bad\nHeading", content: "Body" }])).success).toBe(false);
	});

	it("rejects upsert content containing H2 headings", () => {
		expect(PatchSetSchema.safeParse(patchSet([{ ...basePatch, op: "upsert_section", heading: "Summary", content: "Text\n\n## Nested" }])).success).toBe(false);
	});
});

describe("applyPatchSet", () => {
	it("creates a new file with replace_file", () => {
		const result = applyPatchSet([], patchSet([{
			...basePatch,
			op: "replace_file",
			target: { path: "profile/preferences.md" },
			frontmatter: { source_event_ids: ["e2"], title: "Prefs", type: "note", permalink: "profile/preferences", scope: "profile", last_dreamed_at: "2026-05-12T00:00:00.000Z", confidence: 0.9 },
			markdown: "# Prefs\n\nBody.",
		}]));
		expect(result.errors).toEqual([]);
		expect(result.audit[0]!.action).toBe("created_file");
		expect(result.newWiki[0]!.content).toContain("# Prefs");
	});

	it("rejects replace_file on existing files without allow_overwrite", () => {
		const result = applyPatchSet([baseFile()], patchSet([{ ...basePatch, op: "replace_file", frontmatter: { source_event_ids: ["e2"], title: "Prefs", type: "note", permalink: "profile/preferences", scope: "profile", last_dreamed_at: "2026-05-12T00:00:00.000Z", confidence: 0.9 }, markdown: "# Prefs" }]));
		expect(result.errors[0]!.message).toContain("allow_overwrite");
		expect(result.newWiki[0]!.content).toBe(baseFile().content);
	});

	it("replaces existing files when allow_overwrite is explicit", () => {
		const result = applyPatchSet([baseFile()], patchSet([{ ...basePatch, op: "replace_file", allow_overwrite: true, frontmatter: { source_event_ids: ["e2"], title: "Prefs", type: "note", permalink: "profile/preferences", scope: "profile", last_dreamed_at: "2026-05-12T00:00:00.000Z", confidence: 0.9 }, markdown: "# Prefs\n\nReplaced." }]));
		expect(result.errors).toEqual([]);
		expect(result.audit[0]!.action).toBe("replaced_file");
		expect(result.newWiki[0]!.content).toContain("Replaced.");
	});

	it("upserts an existing H2 section while preserving other hand-edited sections", () => {
		const result = applyPatchSet([baseFile()], patchSet([{ ...basePatch, op: "upsert_section", heading: "Existing", content: "New text." }]));
		expect(result.newWiki[0]!.content).toContain("## Existing\n\nNew text.");
		expect(result.newWiki[0]!.content).toContain("## Keep\n\nHuman text.");
		expect(result.newWiki[0]!.content).not.toContain("Old text.");
	});

	it("appends missing H2 sections for upsert_section", () => {
		const result = applyPatchSet([baseFile()], patchSet([{ ...basePatch, op: "upsert_section", heading: "New Section", content: "New body." }]));
		expect(result.newWiki[0]!.content).toContain("## New Section\n\nNew body.");
	});

	it("rejects section patches for missing files", () => {
		const result = applyPatchSet([], patchSet([{ ...basePatch, op: "upsert_section", heading: "Summary", content: "Body" }]));
		expect(result.errors[0]!.message).toContain("target does not exist");
		expect(result.newWiki).toEqual([]);
	});

	it("resolves targets by permalink", () => {
		const result = applyPatchSet([baseFile()], patchSet([{ id: "p1", source_event_ids: ["e2"], target: { permalink: "profile/preferences" }, op: "upsert_section", heading: "Existing", content: "By permalink." }]));
		expect(result.errors).toEqual([]);
		expect(result.audit[0]!.path).toBe("profile/preferences.md");
		expect(result.newWiki[0]!.content).toContain("By permalink.");
	});

	it("rejects conflicting path and permalink targets", () => {
		const other = { path: "profile/other.md", content: fm(["e1"], "permalink: \"profile/other\"\n") + "# Other\n" };
		const result = applyPatchSet([baseFile(), other], patchSet([{ ...basePatch, target: { path: "profile/preferences.md", permalink: "profile/other" }, op: "upsert_section", heading: "Existing", content: "Nope" }]));
		expect(result.errors[0]!.message).toContain("different files");
	});

	it("rejects duplicate H2 headings as ambiguous", () => {
		const file = baseFile("# Prefs\n\n## Same\n\nA\n\n## Same\n\nB\n");
		const result = applyPatchSet([file], patchSet([{ ...basePatch, op: "upsert_section", heading: "Same", content: "C" }]));
		expect(result.errors[0]!.message).toContain("ambiguous duplicate");
		expect(result.newWiki[0]!.content).toBe(file.content);
	});

	it("unions source_event_ids without duplicates", () => {
		const result = applyPatchSet([baseFile()], patchSet([{ ...basePatch, source_event_ids: ["e1", "e2"], op: "upsert_section", heading: "Existing", content: "New" }]));
		expect(result.newWiki[0]!.content.match(/source_event_ids:\n  - "e1"\n  - "e2"/)).toBeTruthy();
	});

	it("is idempotent for repeated upsert_section patches", () => {
		const ps = patchSet([{ ...basePatch, op: "upsert_section", heading: "Existing", content: "Stable." }]);
		const once = applyPatchSet([baseFile()], ps).newWiki;
		const twice = applyPatchSet(once, ps).newWiki;
		expect(twice).toEqual(once);
	});

	it("dedupes append_to_section blocks on retry", () => {
		const ps = patchSet([{ ...basePatch, op: "append_to_section", heading: "Recall triggers", content: "- alpha\n- beta" }]);
		const once = applyPatchSet([baseFile()], ps).newWiki;
		const twice = applyPatchSet(once, ps).newWiki;
		expect(twice).toEqual(once);
		expect((twice[0]!.content.match(/alpha/g) ?? []).length).toBe(1);
	});

	it("supports line-level append dedupe", () => {
		const file = baseFile("# Prefs\n\n## Recall triggers\n\n- alpha\n");
		const result = applyPatchSet([file], patchSet([{ ...basePatch, op: "append_to_section", heading: "Recall triggers", content: "- alpha\n- beta", dedupe: "line" }]));
		expect(result.newWiki[0]!.content).toContain("- alpha\n\n- beta");
	});

	it("preserves identity frontmatter on section patches", () => {
		const result = applyPatchSet([baseFile()], patchSet([{ ...basePatch, op: "upsert_section", heading: "Existing", content: "New", frontmatter: { permalink: "profile/new", scope: "tools", title: "Changed" } }]));
		expect(result.newWiki[0]!.content).toContain("permalink: \"profile/preferences\"");
		expect(result.newWiki[0]!.content).toContain("scope: \"profile\"");
		expect(result.newWiki[0]!.content).toContain("title: \"Changed\"");
	});

	it("truncates provenance to 200 ids with a marker", () => {
		const ids = Array.from({ length: 200 }, (_, i) => `old-${i}`);
		const result = applyPatchSet([baseFile(undefined,)], patchSet([{ ...basePatch, source_event_ids: ["new-1"], op: "upsert_section", heading: "Existing", content: "New" }]));
		const seeded = { path: "profile/preferences.md", content: fm(ids) + "# Prefs\n\n## Existing\n\nOld\n" };
		const capped = applyPatchSet([seeded], patchSet([{ ...basePatch, source_event_ids: ["new-1"], op: "upsert_section", heading: "Existing", content: "New" }]));
		expect(capped.newWiki[0]!.content).toContain("source_event_ids_truncated_at: \"old-1\"");
		expect(capped.newWiki[0]!.content).not.toContain("old-0");
		expect(capped.newWiki[0]!.content).toContain("new-1");
		expect(result.errors).toEqual([]);
	});

	it("is atomic: any rejected patch leaves all files unchanged", () => {
		const file = baseFile();
		const result = applyPatchSet([file], patchSet([
			{ ...basePatch, op: "upsert_section", heading: "Existing", content: "Would change" },
			{ ...basePatch, id: "bad", target: { path: "profile/missing.md" }, op: "upsert_section", heading: "X", content: "Y" },
		]));
		expect(result.errors).toHaveLength(1);
		expect(result.newWiki).toEqual([file]);
	});

	it("reports noops for equivalent repeated replace_file", () => {
		const ps = patchSet([{ ...basePatch, op: "replace_file", target: { path: "profile/preferences.md" }, frontmatter: { source_event_ids: ["e2"], title: "Prefs", type: "note", permalink: "profile/preferences", scope: "profile", last_dreamed_at: "2026-05-12T00:00:00.000Z", confidence: 0.9 }, markdown: "# Prefs\n\nBody." }]);
		const once = applyPatchSet([], ps).newWiki;
		const twice = applyPatchSet(once, { ...ps, patches: [{ ...(ps.patches[0] as any), allow_overwrite: true }] });
		expect(twice.audit[0]!.action).toBe("noop");
		expect(twice.newWiki).toEqual(once);
	});
});

