/**
 * Path helpers for the tool-agnostic ~/.agents/ memory root.
 *
 * Mirrors Claude Code's path resolution from:
 *   src/memdir/paths.ts       — getAutoMemPath()
 *   src/utils/sessionStoragePortable.ts — sanitizePath()
 *
 * Claude Code:  ~/.claude/projects/<sanitized-git-root>/memory/
 * Ours:         ~/.agents/projects/<sanitized-git-root>/memory/
 *
 * sanitizePath is identical to Claude Code's implementation. Keep in sync.
 */

import { homedir } from "node:os";
import { join } from "node:path";

const MAX_SANITIZED_LENGTH = 200;

function simpleHash(s: string): string {
	let h = 0;
	for (let i = 0; i < s.length; i++) {
		h = (Math.imul(31, h) + s.charCodeAt(i)) | 0;
	}
	return Math.abs(h).toString(36);
}

/**
 * Replicate Claude Code's sanitizePath — replace every non-alphanumeric
 * character with '-', truncating with a hash suffix if over the length cap.
 */
export function sanitizePath(name: string): string {
	const sanitized = name.replace(/[^a-zA-Z0-9]/g, "-");
	if (sanitized.length <= MAX_SANITIZED_LENGTH) return sanitized;
	const hash = simpleHash(name);
	return `${sanitized.slice(0, MAX_SANITIZED_LENGTH)}-${hash}`;
}

/**
 * ~/.agents/projects/<sanitized-git-root>/memory/
 * The write target for agentic dream mode.
 */
export function agentsMemoryRoot(gitRoot: string): string {
	return join(homedir(), ".agents", "projects", sanitizePath(gitRoot), "memory");
}

/**
 * ~/.claude/projects/<sanitized-git-root>/memory/
 * Read-only source context for agentic dream — Claude Code's native memory dir.
 * Only read if it exists; never written to.
 */
export function claudeMemoryRoot(gitRoot: string): string {
	return join(homedir(), ".claude", "projects", sanitizePath(gitRoot), "memory");
}

