/**
 * Backlink graph — built in, the cheap way.
 *
 * The QMD pivot dropped basic-memory's `## Relations` graph because qmd answers
 * "what's *similar*" with embeddings. But an explicit edge set does what
 * embeddings can't: deterministic `links`/`relates`/`supersedes` relations that
 * aid consolidation + dedup, and a graph Obsidian renders for free. We get that
 * by emitting inline `[[permalink]]` links (Obsidian's native backlink source)
 * plus the `links`/`relates` frontmatter — no separate graph store, no qmd change.
 *
 * Pure: string + map operations, no IO.
 */

export type GraphNote = {
	permalink: string;
	markdown: string;
	/** Frontmatter `links` (outbound edges declared structurally). */
	links?: string[];
	/** Frontmatter `relates` (soft "see also" edges). */
	relates?: string[];
};

export type BacklinkIndex = Map<string, string[]>;

const WIKILINK = /\[\[([^\]|]+)(?:\|[^\]]*)?\]\]/g;

/** Extract `[[permalink]]` / `[[permalink|alias]]` targets from a body, in
 * order, de-duplicated. Trims surrounding whitespace from each target. */
export function extractWikiLinks(markdown: string): string[] {
	const out: string[] = [];
	const seen = new Set<string>();
	for (const m of markdown.matchAll(WIKILINK)) {
		const target = m[1]?.trim();
		if (!target || seen.has(target)) continue;
		seen.add(target);
		out.push(target);
	}
	return out;
}

/** Render an inline wiki link, with an optional display alias. */
export function renderWikiLink(permalink: string, alias?: string): string {
	return alias && alias !== permalink ? `[[${permalink}|${alias}]]` : `[[${permalink}]]`;
}

/** All outbound edges for a note: inline `[[links]]` ∪ frontmatter
 * `links` ∪ `relates`, de-duplicated, excluding self-links. */
export function outboundEdges(note: GraphNote): string[] {
	const out: string[] = [];
	const seen = new Set<string>([note.permalink]);
	for (const target of [...extractWikiLinks(note.markdown), ...(note.links ?? []), ...(note.relates ?? [])]) {
		if (seen.has(target)) continue;
		seen.add(target);
		out.push(target);
	}
	return out;
}

/**
 * Build the inbound (backlink) index: target permalink → sorted list of
 * permalinks that link to it. Edges to permalinks not in the note set are still
 * recorded (dangling links are real and worth surfacing). Deterministic order.
 */
export function buildBacklinkIndex(notes: GraphNote[]): BacklinkIndex {
	const index: BacklinkIndex = new Map();
	for (const note of notes) {
		for (const target of outboundEdges(note)) {
			const inbound = index.get(target);
			if (inbound) {
				if (!inbound.includes(note.permalink)) inbound.push(note.permalink);
			} else {
				index.set(target, [note.permalink]);
			}
		}
	}
	for (const inbound of index.values()) inbound.sort();
	return index;
}

const RELATIONS_SECTION = /(^|\n)##\s+relations\b[^\n]*\n([\s\S]*?)(?=\n##\s|\n#\s|$)/i;
const RELATION_TARGET = /\[\[([^\]|]+)(?:\|[^\]]*)?\]\]|(?:^|\s)-\s+([^\n]+)/g;

/**
 * Convert a legacy basic-memory `## Relations` section into inline `[[links]]`,
 * returning the body with the section removed and the harvested targets. This
 * replaces the old *strip-and-drop* behaviour (`dream.ts` stripBasicMemorySections)
 * with *strip-and-keep* — the relations become first-class graph edges instead
 * of being thrown away.
 */
export function convertRelationsToLinks(markdown: string): { markdown: string; links: string[] } {
	const match = RELATIONS_SECTION.exec(markdown);
	if (!match) return { markdown, links: [] };
	const body = match[2] ?? "";
	const links: string[] = [];
	const seen = new Set<string>();
	for (const m of body.matchAll(RELATION_TARGET)) {
		const target = (m[1] ?? m[2])?.trim();
		if (!target || seen.has(target)) continue;
		seen.add(target);
		links.push(target);
	}
	const stripped = markdown.replace(RELATIONS_SECTION, "$1").replace(/\n{3,}/g, "\n\n");
	return { markdown: stripped, links };
}

