/**
 * Canonical store skeleton — create the namespaced directory tree.
 *
 * Idempotent: `mkdir -p` semantics, safe to call on every boot. Creating an
 * empty skeleton is harmless and touches no live recall/injection path, so it
 * cannot churn the prompt-prefix cache (ADR 0008).
 */

import { mkdir } from "node:fs/promises";

import { canonicalDirs, canonicalGlobalRoot, canonicalProjectRoot } from "./paths.ts";

/** Ensure every namespaced subdir exists under one root. Returns the dirs created/ensured. */
export async function ensureCanonicalSkeleton(root: string): Promise<string[]> {
	const dirs = canonicalDirs(root);
	for (const dir of dirs) {
		await mkdir(dir, { recursive: true });
	}
	return dirs;
}

/** Ensure the global root skeleton (`~/.agents/memory`). */
export async function ensureGlobalSkeleton(): Promise<string[]> {
	return ensureCanonicalSkeleton(canonicalGlobalRoot());
}

/** Ensure a project root skeleton (`~/.agents/projects/<slug>/memory`). */
export async function ensureProjectSkeleton(gitRoot: string): Promise<string[]> {
	return ensureCanonicalSkeleton(canonicalProjectRoot(gitRoot));
}

