/**
 * dream-memory active-recall — collection routing.
 *
 * Decides which qmd collections a recall pass queries (memory vs
 * workspace-index vs project-docs) and builds anchored sub-queries.
 * Extracted from active-memory.ts (009). Pure: env + heuristics, no IO.
 */

/**
 * Active-recall collections: pi-memory (live MEMORY.md, daily logs),
 * scars (durable failure patterns), and changes (dated history of
 * agent-scripts changes). Federating across all three on every prompt
 * gives the haiku-curator full context without forcing the user to
 * remember which kind of note they wrote.
 *
 * NOT included: `dream-memory-profile` and `dream-memory-project`. Those are
 * already injected deterministically every session — profile/** via the
 * systemPrompt:build base filter, project/<slug>/** via the SessionStart tail.
 * Recalling them here double-bills the same tokens and (because recall hits
 * land in the volatile region) hurts cross-session cache. Recall should surface
 * memory that is NOT otherwise in the prompt.
 */
export const DEFAULT_ACTIVE_RECALL_COLLECTIONS: readonly string[] = [
	"pi-memory",
	"scars",
	"changes",
] as const;

/** @deprecated single-collection accessor; use {@link activeRecallCollections}. */
export const DEFAULT_ACTIVE_RECALL_COLLECTION: string = DEFAULT_ACTIVE_RECALL_COLLECTIONS[0] ?? "pi-memory";

/**
 * Resolve the collection list for active recall.
 *
 * Override priority:
 *   1. `DREAM_ACTIVE_RECALL_COLLECTIONS` (comma-separated list, plural)
 *   2. `DREAM_ACTIVE_RECALL_COLLECTION` (single, back-compat)
 *   3. `PI_MEMORY_QMD_COLLECTION` (legacy, single)
 *   4. {@link DEFAULT_ACTIVE_RECALL_COLLECTIONS}
 */
/**
 * Generic multi-topic decomposition for two-pass retrieval. Splits the prompt
 * on conjunctions (" and ", " plus ", " & ", "/") when the prompt has ≥6
 * words and ≥2 sub-parts of ≥2 words each. Returns the sub-parts to be used
 * as additional QMD sub-queries (excluding the full query, which the caller
 * still issues). Returns [] for single-topic prompts.
 *
 * Heuristic only — never overfits to specific test cases.
 */
export function decomposeMultiTopic(prompt: string): string[] {
	const trimmed = prompt.trim();
	if (trimmed.split(/\s+/).length < 6) return [];
	const parts = trimmed
		.split(/\s+and\s+|\s+plus\s+|\s+&\s+|\s*\/\s*|\s*,\s*/i)
		.map((p) => p.replace(/[?.!]+$/, "").trim())
		.filter((p) => p.split(/\s+/).length >= 2);
	if (parts.length < 2) return [];
	return parts.slice(0, 4);
}

/**
 * Build anchored follow-up queries for QMD. Smoke prompts and user asks often
 * contain policy prose plus exact file/repo tokens; BM25 can miss the useful
 * docs when everything is searched as one long sentence. Keep the full query,
 * then add short evidence-shaped anchors.
 */
export function buildActiveRecallExtraQueries(prompt: string): string[] {
	const queries: string[] = [];
	const add = (q: string | undefined) => {
		const cleaned = q?.replace(/\s+/g, " ").replace(/[?.!]+$/, "").trim();
		if (!cleaned || cleaned.length < 3) return;
		if (cleaned === prompt.trim()) return;
		if (!queries.includes(cleaned)) queries.push(cleaned);
	};

	const question = /\bQuestion:\s*([\s\S]*?)(?:\n\s*\n|\bExpected\b|\bAnswer\b|$)/i.exec(prompt)?.[1];
	const corePrompt = question ?? prompt;
	add(question);
	add(corePrompt
		.replace(/\b(where|which|what|find|locate|path|repo|repository|project|workspace|checkout|source|stored|local|the|is|are|do|does|can|you|please)\b/gi, " ")
		.replace(/\bsrc\b/gi, "src source")
	);
	for (const q of decomposeMultiTopic(corePrompt)) add(q);

	for (const m of prompt.matchAll(/`([^`]+)`/g)) add(m[1]);
	for (const m of prompt.matchAll(/(?:^|\s)((?:[\w.-]+\/)+[\w.-]+\.md)\b/g)) add(m[1]);
