export function activeRecallCollections(): string[] {
	const plural = process.env.DREAM_ACTIVE_RECALL_COLLECTIONS;
	if (plural) {
		const list = plural.split(",").map((s) => s.trim()).filter(Boolean);
		if (list.length > 0) return list;
	}
	const single =
		process.env.DREAM_ACTIVE_RECALL_COLLECTION ??
		process.env.PI_MEMORY_QMD_COLLECTION;
	if (single) return [single];
	return [...DEFAULT_ACTIVE_RECALL_COLLECTIONS];
}

