	return /\b(where|which|what|find|locate|path|repo|repository|project|workspace|checkout|source|src|directory|folder)\b/i.test(prompt);
}

function looksLikeProjectDocsLookup(prompt: string): boolean {
	return /\b(doc|docs|documentation|research|spec|prd|plan|proposal|design|runbook|architecture|decision|adr|notes?)\b/i.test(prompt);
}

function projectDocsCollectionForSlug(slug: string | undefined): string | undefined {
	if (!slug || slug === "unknown") return undefined;
	return `project-docs-${slug}`;
}

export function resolveActiveRecallRoute(prompt: string, projectSlug?: string): RecallCollectionRoute {
	if (hasExplicitRecallCollectionsEnv()) {
		return { collections: activeRecallCollections(), reason: "explicit-env" };
	}
	const projectDocs = projectDocsCollectionForSlug(projectSlug);
	const globalMemory = activeRecallCollections();
	if (looksLikeWorkspaceLookup(prompt)) {
		const primaryCollections = ["workspace-index", "workspace-info", ...(projectDocs ? [projectDocs] : [])];
		return {
			collections: [...primaryCollections, ...globalMemory],
			primaryCollections,
			globalCollections: globalMemory,
			qmdMode: "search",
			reason: "workspace",
		};
	}
	if (projectDocs && looksLikeProjectDocsLookup(prompt)) {
		const primaryCollections = [projectDocs];
		return {
			collections: [...primaryCollections, ...globalMemory],
			primaryCollections,
			globalCollections: globalMemory,
			qmdMode: "search",
			reason: "project-docs",
		};
	}
	return { collections: activeRecallCollections(), reason: "default-memory" };
}

/** @deprecated returns only the first collection; use {@link activeRecallCollections}. */
export function activeRecallCollection(): string {
	return activeRecallCollections()[0] ?? DEFAULT_ACTIVE_RECALL_COLLECTION;
}

