/** @deprecated single-collection accessor; use {@link activeRecallCollections}. */
export const DEFAULT_ACTIVE_RECALL_COLLECTION: string = DEFAULT_ACTIVE_RECALL_COLLECTIONS[0] ?? "pi-memory";

// ---------------------------------------------------------------------------
// Canonical collections + dual-read shim (P1). Recognised here BEFORE the qmd
// cutover (H3) so routing is ready when the canonical corpus lands (P2). The
// dual-read path is **default-OFF** — flipping it on is the cutover lever (P7).
// Default-off keeps daily-driver routing byte-identical, so P1 cannot churn the
// prompt-prefix cache (ADR 0008).

/** qmd collection-name prefix for the canonical store. */
export const CANONICAL_COLLECTION_PREFIX = "canonical";

/** Legacy collections still queried during the dual-read transition. */
export const LEGACY_RECALL_COLLECTIONS: readonly string[] = [
	"pi-memory",
	"dream-memory-profile",
	"dream-memory-project",
	"scars",
	"changes",
] as const;

/** Canonical qmd collections: `canonical-shared`, `canonical-harness-<id>` per
 * harness, `canonical-episodic`. Stable, alias-free names (one harness-ID enum). */
export function canonicalCollections(harnesses: readonly HarnessId[] = HARNESS_IDS): string[] {
	return [
		`${CANONICAL_COLLECTION_PREFIX}-shared`,
		...harnesses.map((h) => `${CANONICAL_COLLECTION_PREFIX}-harness-${h}`),
		`${CANONICAL_COLLECTION_PREFIX}-episodic`,
	];
}

/** Is canonical (dual-read) recall enabled? Default OFF. */
export function canonicalRecallEnabled(): boolean {
	return process.env.DREAM_CANONICAL_RECALL === "1" || process.env.DREAM_CANONICAL_RECALL === "true";
}

/** Dual-read collection list: the supplied base ∪ canonical collections, but
 * only when {@link canonicalRecallEnabled}. Returns the base unchanged otherwise
 * (the no-op path daily-driver sessions take). */
export function dualReadCollections(base: readonly string[]): string[] {
	if (!canonicalRecallEnabled()) return [...base];
	const out = [...base];
	for (const c of canonicalCollections()) if (!out.includes(c)) out.push(c);
	return out;
}

/** Minimal hit shape for tail-only dual-read dedup — structural, so it never
 * needs to import the heavy SearchHit type. */
export type DualReadHit = { source_id?: string; permalink?: string; title?: string; file_path?: string };

/** Stable identity for dedup across legacy + canonical reads: prefer an exact
 * source id, then permalink, then a title∕path composite. (Exact-ID/permalink
 * match only — never embedding similarity; ADR 0007 D5.) */
export function dualReadKey(hit: DualReadHit): string {
	return hit.source_id ?? hit.permalink ?? `${hit.title ?? ""}�${hit.file_path ?? ""}`;
}

/** Suppress duplicates across dual-read results, keeping the first occurrence.
 * Callers order canonical-vs-legacy by preference before calling. TAIL-ONLY —
 * this runs on volatile recall hits, never on cached-core bytes. */
export function dedupeDualRead<T extends DualReadHit>(hits: readonly T[]): T[] {
	const seen = new Set<string>();
	const out: T[] = [];
	for (const h of hits) {
		const k = dualReadKey(h);
		if (seen.has(k)) continue;
		seen.add(k);
		out.push(h);
	}
	return out;
}

