import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { mkdtemp, rm, stat } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

import {
	canonicalDirs,
	canonicalGlobalRoot,
	canonicalProjectRoot,
	episodicDir,
	HARNESS_IDS,
	harnessDir,
	inboxDir,
	isHarnessId,
	sharedDir,
} from "../src/canonical/paths.ts";
import {
	CanonicalFrontmatterSchema,
	defaultCaptureVisibility,
} from "../src/canonical/frontmatter.ts";
import {
	buildBacklinkIndex,
	convertRelationsToLinks,
	extractWikiLinks,
	outboundEdges,
	renderWikiLink,
} from "../src/canonical/backlinks.ts";
import { ensureCanonicalSkeleton } from "../src/canonical/skeleton.ts";
import {
	canonicalCollections,
	canonicalRecallEnabled,
	dedupeDualRead,
	dualReadCollections,
	dualReadKey,
	LEGACY_RECALL_COLLECTIONS,
} from "../src/active-memory/recall-routing.ts";

// ---------------------------------------------------------------------------

describe("canonical/paths — per-project + global split", () => {
	it("the harness-ID enum is pi/claude-code/codex with no aliases", () => {
		expect([...HARNESS_IDS]).toEqual(["pi", "claude-code", "codex"]);
		expect(isHarnessId("pi")).toBe(true);
		expect(isHarnessId("claude-code")).toBe(true);
		expect(isHarnessId("cc")).toBe(false);
		expect(isHarnessId("claude")).toBe(false);
	});

	it("global root honours AGENTS_MEMORY_HOME, else ~/.agents/memory", () => {
		const prev = process.env.AGENTS_MEMORY_HOME;
		try {
			process.env.AGENTS_MEMORY_HOME = "/tmp/canon-global";
			expect(canonicalGlobalRoot()).toBe("/tmp/canon-global");
			delete process.env.AGENTS_MEMORY_HOME;
			expect(canonicalGlobalRoot()).toMatch(/\.agents\/memory$/);
		} finally {
			if (prev === undefined) delete process.env.AGENTS_MEMORY_HOME;
			else process.env.AGENTS_MEMORY_HOME = prev;
		}
	});

	it("project root is ~/.agents/projects/<sanitized>/memory", () => {
		const root = canonicalProjectRoot("/Users/luke/Projects/personal/my-pi");
		expect(root).toMatch(/\.agents\/projects\/Users-luke-Projects-personal-my-pi\/memory$/);
	});

	it("every root carries shared/ + harness/<id> + episodic/ + inbox/", () => {
		const root = "/tmp/canon";
		expect(canonicalDirs(root)).toEqual([
			sharedDir(root),
			harnessDir(root, "pi"),
			harnessDir(root, "claude-code"),
			harnessDir(root, "codex"),
			episodicDir(root),
			inboxDir(root),
		]);
		expect(harnessDir(root, "claude-code")).toBe("/tmp/canon/harness/claude-code");
	});
});

// ---------------------------------------------------------------------------

describe("canonical/frontmatter — structured contract, origin ≠ visibility", () => {
	const valid = {
		title: "Prefers dashes",
		permalink: "shared/style",
		origin: "codex" as const,
		visibility: "shared",
		sensitivity: "public" as const,
		scope: "profile",
		confidence: "consolidated" as const,
		provenance: { source_store: "codex-memories" as const, source_path: "memories.md", capture_mechanism: "harvest" as const },
	};

	it("accepts a well-formed canonical record", () => {
		expect(CanonicalFrontmatterSchema.safeParse(valid).success).toBe(true);
	});

	it("origin is a harness-ID enum, decoupled from visibility", () => {
		expect(CanonicalFrontmatterSchema.safeParse({ ...valid, origin: "obsidian" }).success).toBe(false);
		// origin codex + visibility private is a legal combination — never inferred.
		expect(CanonicalFrontmatterSchema.safeParse({ ...valid, origin: "codex", visibility: "private" }).success).toBe(true);
	});

	it("visibility accepts private|shared|harness:<x>|project:<slug>, rejects junk", () => {
		for (const v of ["private", "shared", "harness:pi", "project:my-pi"]) {
			expect(CanonicalFrontmatterSchema.safeParse({ ...valid, visibility: v }).success).toBe(true);
		}
		expect(CanonicalFrontmatterSchema.safeParse({ ...valid, visibility: "public" }).success).toBe(false);
	});

	it("scope accepts profile|project:|tool:|harness:, rejects junk", () => {
		for (const s of ["profile", "project:my-pi", "tool:qmd", "harness:codex"]) {
			expect(CanonicalFrontmatterSchema.safeParse({ ...valid, scope: s }).success).toBe(true);
		}
		expect(CanonicalFrontmatterSchema.safeParse({ ...valid, scope: "everything" }).success).toBe(false);
	});

	it("requires provenance source_store + path + capture_mechanism", () => {
		expect(CanonicalFrontmatterSchema.safeParse({ ...valid, provenance: { source_store: "pi" } }).success).toBe(false);
	});

	it("default capture is origin-private (never shared until classified)", () => {
		expect(defaultCaptureVisibility()).toEqual({ visibility: "private", sensitivity: "private" });
	});
});

// ---------------------------------------------------------------------------

describe("canonical/backlinks — the graph, built in", () => {
	it("extracts [[permalink]] and [[permalink|alias]], deduped, in order", () => {
		expect(extractWikiLinks("see [[a/one]] and [[b/two|Two]] and [[a/one]] again")).toEqual(["a/one", "b/two"]);
	});

	it("renders inline links with optional alias", () => {
		expect(renderWikiLink("a/one")).toBe("[[a/one]]");
		expect(renderWikiLink("a/one", "One")).toBe("[[a/one|One]]");
		expect(renderWikiLink("a/one", "a/one")).toBe("[[a/one]]");
	});

	it("outbound edges = inline ∪ links ∪ relates, excluding self", () => {
		const edges = outboundEdges({
			permalink: "x/self",
			markdown: "links to [[a/one]]",
			links: ["b/two", "x/self"],
			relates: ["c/three", "a/one"],
		});
		expect(edges).toEqual(["a/one", "b/two", "c/three"]);
	});

	it("builds an inbound backlink index, sorted, keeping dangling edges", () => {
		const index = buildBacklinkIndex([
			{ permalink: "p/a", markdown: "[[p/c]]" },
			{ permalink: "p/b", markdown: "see [[p/c]] and [[p/missing]]" },
		]);
		expect(index.get("p/c")).toEqual(["p/a", "p/b"]);
		expect(index.get("p/missing")).toEqual(["p/b"]); // dangling, still recorded
	});

	it("converts a legacy ## Relations section to links instead of dropping it", () => {
		const md = "# Note\n\nBody.\n\n## Relations\n\n- relates_to [[p/x]]\n- [[p/y]]\n\n## Keep\n\nkept.\n";
		const { markdown, links } = convertRelationsToLinks(md);
		expect(links).toContain("p/x");
		expect(links).toContain("p/y");
		expect(markdown).not.toContain("## Relations");
		expect(markdown).toContain("## Keep"); // other sections survive
	});
});

// ---------------------------------------------------------------------------

describe("canonical/skeleton — idempotent dir tree", () => {
	let scratch: string;
	beforeEach(async () => { scratch = await mkdtemp(join(tmpdir(), "canon-skel-")); });
	afterEach(async () => { await rm(scratch, { recursive: true, force: true }); });

	it("creates every namespaced subdir and is safe to re-run", async () => {
		const root = join(scratch, "memory");
		const made = await ensureCanonicalSkeleton(root);
		expect(made).toEqual(canonicalDirs(root));
		for (const dir of made) expect((await stat(dir)).isDirectory()).toBe(true);
		// idempotent
		await expect(ensureCanonicalSkeleton(root)).resolves.toEqual(canonicalDirs(root));
	});
});

// ---------------------------------------------------------------------------

describe("recall-routing — canonical collections + dual-read (default OFF)", () => {
	afterEach(() => { delete process.env.DREAM_CANONICAL_RECALL; });

	it("canonical collection names are stable and alias-free", () => {
		expect(canonicalCollections()).toEqual([
			"canonical-shared",
			"canonical-harness-pi",
			"canonical-harness-claude-code",
			"canonical-harness-codex",
			"canonical-episodic",
		]);
	});

	it("dual-read is OFF by default → base list returned unchanged", () => {
		expect(canonicalRecallEnabled()).toBe(false);
		const base = [...LEGACY_RECALL_COLLECTIONS];
		expect(dualReadCollections(base)).toEqual(base); // no daily-driver churn
	});

