/**
 * Canonical cross-harness memory store — path + namespace resolution.
 *
 * Layout locked 2026-06-22 (ADR 0007 D1, spec P1): a per-project + global split.
 *   global   ~/.agents/memory/{shared,harness/<id>,episodic,inbox}
 *   project  ~/.agents/projects/<sanitize(gitRoot)>/memory/{shared,harness/<id>,episodic,inbox}
 *
 * The per-project root is exactly Claude Code's convention and the existing
 * agentic-dream write target (`agentsMemoryRoot`); the global root holds
 * profile/cross-project facts. `scope` frontmatter records global-vs-project so
 * a misfiled note stays classifiable. Pure: no IO, env-overridable root only.
 */

import { homedir } from "node:os";
import { join } from "node:path";

import { agentsMemoryRoot } from "../lib/agents-path.ts";

/** The one canonical harness-ID enum — used in paths, provenance, qmd collection
 * names, tests, and docs. No informal aliases (`cc`, `claude`, …). */
export const HARNESS_IDS = ["pi", "claude-code", "codex"] as const;
export type HarnessId = (typeof HARNESS_IDS)[number];

export function isHarnessId(value: string): value is HarnessId {
	return (HARNESS_IDS as readonly string[]).includes(value);
}

/** Namespaced subdirectories present under every canonical root. */
export const CANONICAL_SUBDIRS = ["shared", "harness", "episodic", "inbox"] as const;

/**
 * Global / cross-project canonical root: `~/.agents/memory`.
 * Overridable via `AGENTS_MEMORY_HOME` (testing + relocation).
 */
export function canonicalGlobalRoot(): string {
	const override = process.env.AGENTS_MEMORY_HOME;
	return override && override.length > 0 ? override : join(homedir(), ".agents", "memory");
}

/**
 * Per-project canonical root: `~/.agents/projects/<sanitize(gitRoot)>/memory`.
 * Delegates to {@link agentsMemoryRoot} so the project sanitisation stays in
 * one place (kept byte-identical to Claude Code's).
 */
export function canonicalProjectRoot(gitRoot: string): string {
	return agentsMemoryRoot(gitRoot);
}

/** `<root>/shared` — cross-harness facts in that root's scope. */
export function sharedDir(root: string): string {
	return join(root, "shared");
}

/** `<root>/harness/<id>` — facts specific to one harness. */
export function harnessDir(root: string, harness: HarnessId): string {
	return join(root, "harness", harness);
}

/** `<root>/episodic` — chronicle / time-ordered captures. */
export function episodicDir(root: string): string {
	return join(root, "episodic");
}

/** `<root>/inbox` — append-only raw capture (all sources, incl. Pi). */
export function inboxDir(root: string): string {
	return join(root, "inbox");
}

/** Every directory that {@link canonicalGlobalRoot}/{@link canonicalProjectRoot}
 * must contain. Order is stable for deterministic skeleton creation + tests. */
export function canonicalDirs(root: string): string[] {
	return [
		sharedDir(root),
		...HARNESS_IDS.map((id) => harnessDir(root, id)),
		episodicDir(root),
		inboxDir(root),
	];
}

