/** One store's extraction output: its claims + the files it deliberately skipped. */
export type StoreExtraction = {
	source_store: ClaimSourceStore;
	root: string;
	/** Every file the extractor saw (claim sources ∪ skips must equal this set). */
	files_seen: string[];
	claims: Claim[];
	skipped: Skipped[];
};

