/** Extractor registry — one read-only claim extractor per physical store. */

import type { ClaimSourceStore, StoreExtraction } from "../ledger.ts";
import { extractClaudeCode } from "./cc.ts";
import { extractCodex } from "./codex.ts";
import { extractObsidian } from "./obsidian.ts";
import { extractPi } from "./pi.ts";

export type Extractor = (root: string) => Promise<StoreExtraction>;

export const EXTRACTORS: Record<ClaimSourceStore, Extractor> = {
	pi: extractPi,
	obsidian: extractObsidian,
	"claude-code": extractClaudeCode,
	codex: extractCodex,
};

export { extractClaudeCode, extractCodex, extractObsidian, extractPi };

/**
 * Codex memories extractor (`~/.codex/memories`). Read-only source. No
 * frontmatter — `MEMORY.md` (≈300 KB) and `raw_memories.md` (≈450 KB) are
 * heading-delimited, so each file is chunked into section claims with byte-span
 * fidelity (spans tile the file, gap-free). Most sections are rollout/task
 * episodes (→ episodic); preference/knowledge sections hint profile/reference.
 */

import { makeClaim, type Claim, type ClaimSourceStore, type ScopeHint, type Skipped, type StoreExtraction } from "../ledger.ts";
import { detectMinHeadingLevel, splitSections } from "../parse.ts";
import { asString, listMarkdownFiles, mtimeIso, readText } from "./util.ts";

const STORE: ClaimSourceStore = "codex";

function scopeFromHeading(heading: string | undefined): ScopeHint {
	const h = (heading ?? "").toLowerCase();
	if (h.includes("preference")) return "profile";
	if (h.includes("reusable knowledge") || h.includes("knowledge")) return "reference";
	if (h.includes("failure")) return "reference";
	return "episodic"; // task / rollout / keywords / default
}

export async function extractCodex(root: string): Promise<StoreExtraction> {
	const files = await listMarkdownFiles(root);
	const claims: Claim[] = [];
	const skipped: Skipped[] = [];

	for (const rel of files) {
		const text = await readText(root, rel);
		if (!text.trim()) {
			skipped.push({ source_store: STORE, path: rel, reason: "empty file" });
			continue;
		}
		const captured_at = await mtimeIso(root, rel);
		const level = detectMinHeadingLevel(text) ?? 2;
		const sections = splitSections(text, level);
		let made = 0;
		for (const s of sections) {
			if (!s.text.trim()) continue; // degenerate heading-only / blank slice
			made++;
			claims.push(
				makeClaim({
					source_store: STORE,
					source_path: rel,
					span: { kind: "section", start: s.start, end: s.end, heading: s.heading },
					scope_hint: scopeFromHeading(s.heading),
					title: asString(s.heading) ?? rel.split("/").pop(),
					captured_at,
					text: s.text,
				}),
			);
		}
		if (made === 0) skipped.push({ source_store: STORE, path: rel, reason: "no extractable sections" });
	}
	return { source_store: STORE, root, files_seen: files, claims, skipped };
}

/**
 * Claude Code native-memory extractor (`~/.claude/projects/<slug>/memory`).
 * Read-only source. Each file is one fact (whole-file claim) with nested
 * frontmatter `name`/`description`/`metadata.{node_type,type}`. `MEMORY.md` is
 * the generated index, not a fact — skipped with a reason.
 */

import { makeClaim, type Claim, type ClaimSourceStore, type Skipped, type StoreExtraction } from "../ledger.ts";
import { parseFrontmatter } from "../parse.ts";
import { asString, listMarkdownFiles, mtimeIso, readText, scopeFromType } from "./util.ts";

const STORE: ClaimSourceStore = "claude-code";

function metaType(data: Record<string, unknown>): unknown {
	const meta = data.metadata;
	if (meta && typeof meta === "object" && !Array.isArray(meta)) return (meta as Record<string, unknown>).type;
	return undefined;
}

export async function extractClaudeCode(root: string): Promise<StoreExtraction> {
	const files = await listMarkdownFiles(root);
	const claims: Claim[] = [];
	const skipped: Skipped[] = [];

	for (const rel of files) {
		const base = rel.split("/").pop() ?? rel;
		if (base === "MEMORY.md") {
			skipped.push({ source_store: STORE, path: rel, reason: "generated index, not a fact" });
			continue;
		}
		const text = await readText(root, rel);
		if (!text.trim()) {
			skipped.push({ source_store: STORE, path: rel, reason: "empty file" });
			continue;
		}
		const { data } = parseFrontmatter(text);

		claims.push(
			makeClaim({
				source_store: STORE,
				source_path: rel,
				span: { kind: "whole" },
				scope_hint: scopeFromType(metaType(data)),
				title: asString(data.name),
				captured_at: await mtimeIso(root, rel),
				text,
				origin_meta: Object.keys(data).length ? data : undefined,
			}),
		);
	}
	return { source_store: STORE, root, files_seen: files, claims, skipped };
}

/**
 * Obsidian dream-wiki extractor (`~/obsidian/dream-memory/memory`). Full member.
 * Each file is one consolidated fact (whole-file claim) with the legacy dream
 * frontmatter: `source_event_ids`/`title`/`permalink`/`scope`/`confidence`/
 * `last_dreamed_at`. `scope` and a `project/<slug>/` path drive the hints.
 */

import { makeClaim, type Claim, type ClaimSourceStore, type Skipped, type StoreExtraction } from "../ledger.ts";
import { parseFrontmatter } from "../parse.ts";
import { asString, listMarkdownFiles, readText, scopeFromType } from "./util.ts";

const STORE: ClaimSourceStore = "obsidian";

export async function extractObsidian(root: string): Promise<StoreExtraction> {
	const files = await listMarkdownFiles(root);
	const claims: Claim[] = [];
	const skipped: Skipped[] = [];

	for (const rel of files) {
		const text = await readText(root, rel);
		if (!text.trim()) {
			skipped.push({ source_store: STORE, path: rel, reason: "empty file" });
			continue;
		}
		const { data } = parseFrontmatter(text);
		const parts = rel.split("/");
		const scope_hint = scopeFromType(data.scope);
		const project_slug = parts[0] === "project" ? parts[1] : undefined;

		claims.push(
			makeClaim({
				source_store: STORE,
				source_path: rel,
				span: { kind: "whole" },
				scope_hint,
				project_slug,
				title: asString(data.title),
				captured_at: asString(data.last_dreamed_at),
				text,
				origin_meta: Object.keys(data).length ? data : undefined,
			}),
		);
	}
	return { source_store: STORE, root, files_seen: files, claims, skipped };
}

