/** The four physical legacy roots. Distinct from the canonical `SourceStoreSchema`
 * (which also splits `codex-memories`/`chronicle`); the reconciler (P2b) maps a
 * claim's physical store to a canonical provenance store when it writes. */
export const CLAIM_SOURCE_STORES = ["pi", "obsidian", "claude-code", "codex"] as const;
export type ClaimSourceStore = (typeof CLAIM_SOURCE_STORES)[number];

/** A claim's location within its source file: the whole file, or a byte range
 * (chunked big files). Sections of one file are contiguous + gap-free. */
export const SpanSchema = z.discriminatedUnion("kind", [
	z.object({ kind: z.literal("whole") }),
	z.object({
		kind: z.literal("section"),
		start: z.number().int().nonnegative(),
		end: z.number().int().nonnegative(),
		heading: z.string().min(1).optional(),
	}),
]);
export type Span = z.infer<typeof SpanSchema>;

export const SCOPE_HINTS = ["profile", "project", "reference", "tool", "episodic", "inbox", "unknown"] as const;
export const ScopeHintSchema = z.enum(SCOPE_HINTS);
export type ScopeHint = z.infer<typeof ScopeHintSchema>;

export const ClaimSchema = z.object({
	claim_id: z.string().min(1),
	source_store: z.enum(CLAIM_SOURCE_STORES),
	/** Root-relative path within the source store. */
	source_path: z.string().min(1),
	span: SpanSchema,
	/** sha256 of the normalised claim text — the dedup / idempotency key. */
	content_hash: z.string().min(1),
	captured_at: z.string().min(1).optional(),
	scope_hint: ScopeHintSchema,
	project_slug: z.string().min(1).optional(),
	title: z.string().min(1).optional(),
	/** The raw claim text (frontmatter + body, or the section slice). */
	text: z.string(),
	/** Raw parsed frontmatter, retained for audit/reconciliation. */
	origin_meta: z.record(z.unknown()).optional(),
});
export type Claim = z.infer<typeof ClaimSchema>;

// ---------------------------------------------------------------------------
// Deterministic derivation

/** Normalise for stable hashing: CRLF→LF, strip per-line trailing whitespace,
 * trim leading/trailing blank lines. Two byte-different-but-semantically-equal
 * captures hash identically. */
export function normaliseText(text: string): string {
	return text
		.replace(/\r\n?/g, "\n")
		.split("\n")
		.map((line) => line.replace(/[ \t]+$/, ""))
		.join("\n")
		.replace(/^\n+/, "")
		.replace(/\n+$/, "");
}

export function contentHash(text: string): string {
	return createHash("sha256").update(normaliseText(text)).digest("hex");
}

/** Stable string form of a span, for the claim_id pre-image. */
export function spanKey(span: Span): string {
	return span.kind === "whole" ? "whole" : `section:${span.start}-${span.end}`;
}

/** Content-addressed claim id: sha256 over the locating tuple, hex-truncated.
 * Same source span + same content ⇒ same id across runs (idempotency). */
export function deriveClaimId(
	source_store: ClaimSourceStore,
	source_path: string,
	span: Span,
	content_hash: string,
): string {
	const preimage = [source_store, source_path, spanKey(span), content_hash].join("�");
	return createHash("sha256").update(preimage).digest("hex").slice(0, 32);
}

/** Claim fields the extractor supplies; `content_hash`/`claim_id` are derived.
 * Optionals admit `undefined` explicitly so call sites can pass a maybe-absent
 * value without an `exactOptionalPropertyTypes` dance. */
export type ClaimInput = {
	source_store: ClaimSourceStore;
	source_path: string;
	span: Span;
	scope_hint: ScopeHint;
	text: string;
	captured_at?: string | undefined;
	project_slug?: string | undefined;
	title?: string | undefined;
	origin_meta?: Record<string, unknown> | undefined;
};

/** Build a validated claim, deriving `content_hash` + `claim_id` from `text`.
 * Undefined optionals are dropped so the parsed record stays clean. */
export function makeClaim(input: ClaimInput): Claim {
	const content_hash = contentHash(input.text);
	const claim_id = deriveClaimId(input.source_store, input.source_path, input.span, content_hash);
	const candidate: Record<string, unknown> = { ...input, content_hash, claim_id };
	for (const k of Object.keys(candidate)) if (candidate[k] === undefined) delete candidate[k];
	return ClaimSchema.parse(candidate);
}

// ---------------------------------------------------------------------------
// Ledger manifest (the no-drops accounting)

/** A source file skipped during extraction, with the reason — so every source
 * file is accounted for as either a claim source or an explicit skip. */
export const SkippedSchema = z.object({
	source_store: z.enum(CLAIM_SOURCE_STORES),
	path: z.string().min(1),
	reason: z.string().min(1),
});
export type Skipped = z.infer<typeof SkippedSchema>;

export const SourceSummarySchema = z.object({
	source_store: z.enum(CLAIM_SOURCE_STORES),
	root: z.string().min(1),
	file_count: z.number().int().nonnegative(),
	claim_count: z.number().int().nonnegative(),
});
export type SourceSummary = z.infer<typeof SourceSummarySchema>;

export const LedgerManifestSchema = z.object({
	version: z.literal(1),
	generated_at: z.string().min(1),
	sources: z.array(SourceSummarySchema),
	total_claims: z.number().int().nonnegative(),
	skipped: z.array(SkippedSchema),
});
export type LedgerManifest = z.infer<typeof LedgerManifestSchema>;

/** One store's extraction output: its claims + the files it deliberately skipped. */
export type StoreExtraction = {
	source_store: ClaimSourceStore;
	root: string;
	/** Every file the extractor saw (claim sources ∪ skips must equal this set). */
	files_seen: string[];
	claims: Claim[];
	skipped: Skipped[];
};

