/**
 * Shared extractor utilities — read-only filesystem walking + scope mapping.
 * Every extractor reports `files_seen` so the dry-run can prove claims ∪ skips
 * tile the whole scanned set (no silent drops).
 */

import { readdir, readFile, stat } from "node:fs/promises";
import { join, relative } from "node:path";

import type { ScopeHint } from "../ledger.ts";

/** Recursively list `.md` files under `root` (or under given `subdirs` of it),
 * returned as sorted root-relative paths. Missing subdirs are skipped, not an
 * error — a store may not have every namespace. */
export async function listMarkdownFiles(root: string, opts?: { subdirs?: string[] }): Promise<string[]> {
	const out: string[] = [];
	const bases = opts?.subdirs ? opts.subdirs.map((s) => join(root, s)) : [root];
	for (const base of bases) await walk(base, root, out);
	return out.sort();
}

async function walk(dir: string, root: string, out: string[]): Promise<void> {
	let entries;
	try {
		entries = await readdir(dir, { withFileTypes: true });
	} catch {
		return; // missing/unreadable dir → nothing to add
	}
	for (const e of entries) {
		const full = join(dir, e.name);
		if (e.isDirectory()) await walk(full, root, out);
		else if (e.isFile() && e.name.endsWith(".md")) out.push(relative(root, full));
	}
}

export async function readText(root: string, rel: string): Promise<string> {
	return readFile(join(root, rel), "utf8");
}

export async function mtimeIso(root: string, rel: string): Promise<string | undefined> {
	try {
		return (await stat(join(root, rel))).mtime.toISOString();
	} catch {
		return undefined;
	}
}

/** A leading `YYYY-MM-DD` in a filename → ISO date, for dated log files. */
export function dateFromFilename(rel: string): string | undefined {
	const m = /(\d{4}-\d{2}-\d{2})/.exec(rel.split("/").pop() ?? "");
	return m ? `${m[1]}T00:00:00Z` : undefined;
}

/** Map a legacy `type`/`scope` string to a {@link ScopeHint}. A hint only — the
 * reconciler (P2b) decides final scope. */
export function scopeFromType(type: unknown): ScopeHint {
	switch (String(type ?? "").toLowerCase()) {
		case "project":
			return "project";
		case "reference":
			return "reference";
		case "tool":
		case "tools":
			return "tool";
		case "profile":
		case "user":
		case "feedback":
			return "profile";
		case "inbox":
			return "inbox";
		case "episodic":
			return "episodic";
		default:
			return "unknown";
	}
}

export function asString(v: unknown): string | undefined {
	return typeof v === "string" && v.trim() ? v.trim() : undefined;
}

