export type Section = { heading?: string; level?: number; start: number; end: number; text: string };

/** A fenced-code-block opener/closer: ``` or ~~~ (≥3, indented ≤3 spaces). Returns
 * the marker run so a closer can be matched to its opener (same char, ≥ length). */
function fenceMarker(line: string): string | null {
	const m = /^ {0,3}(`{3,}|~{3,})/.exec(line);
	return m ? (m[1] ?? null) : null;
}

/** Heading positions (code-unit offset + trimmed text) at exactly `level`,
 * skipping any `#` line inside a fenced code block. Walks line-by-line tracking
 * fence state; offsets are accumulated so spans round-trip via `text.slice`.
 * Tolerant of CRLF: `.` stops before `\r` and the heading is trimmed. */
function headingMarks(text: string, level: number): { idx: number; heading: string }[] {
	const headingRe = new RegExp(`^#{${level}}[ \\t]+(.*)`);
	const marks: { idx: number; heading: string }[] = [];
	let fence: string | null = null;
	let offset = 0;
	for (const line of text.split("\n")) {
		const marker = fenceMarker(line);
		if (fence === null) {
			if (marker) {
				fence = marker;
			} else {
				const m = headingRe.exec(line);
				if (m) marks.push({ idx: offset, heading: (m[1] ?? "").trim() });
			}
		} else if (marker && marker[0] === fence[0] && marker.length >= fence.length) {
			fence = null; // matching closer ends the fence
		}
		offset += line.length + 1; // + the "\n" consumed by split
	}
	return marks;
}

