		expect(normaliseText("\n\n\nbody\n\n\n")).toBe("body");
		// interior blank lines are preserved (only leading/trailing are trimmed)
		expect(normaliseText("a\n\nb")).toBe("a\n\nb");
	});

	it("contentHash is stable across byte-equivalent captures", () => {
		expect(contentHash("hello\nworld")).toBe(contentHash("hello  \r\nworld\n\n"));
		expect(contentHash("a")).not.toBe(contentHash("b"));
	});

	it("spanKey distinguishes whole vs section ranges", () => {
		expect(spanKey({ kind: "whole" })).toBe("whole");
		expect(spanKey({ kind: "section", start: 0, end: 12 })).toBe("section:0-12");
		// heading does not enter the key — only the byte range locates the claim
		const a: Span = { kind: "section", start: 0, end: 12, heading: "A" };
		const b: Span = { kind: "section", start: 0, end: 12, heading: "B" };
		expect(spanKey(a)).toBe(spanKey(b));
	});

	it("deriveClaimId is content-addressed and span-sensitive", () => {
		const h = contentHash("body");
		const id1 = deriveClaimId("pi", "profile/x.md", { kind: "whole" }, h);
		const id2 = deriveClaimId("pi", "profile/x.md", { kind: "whole" }, h);
		expect(id1).toBe(id2);
		expect(id1).toHaveLength(32);
		// different store, path, span, or content all fork the id
		expect(deriveClaimId("obsidian", "profile/x.md", { kind: "whole" }, h)).not.toBe(id1);
		expect(deriveClaimId("pi", "profile/y.md", { kind: "whole" }, h)).not.toBe(id1);
		expect(deriveClaimId("pi", "profile/x.md", { kind: "section", start: 0, end: 4 }, h)).not.toBe(id1);
		expect(deriveClaimId("pi", "profile/x.md", { kind: "whole" }, contentHash("other"))).not.toBe(id1);
	});

	it("makeClaim derives hash+id, drops undefined optionals, and validates", () => {
		const claim = makeClaim({
			source_store: "pi",
			source_path: "profile/coffee.md",
			span: { kind: "whole" },
			scope_hint: "profile",
			text: "Luke likes coffee",
			title: undefined,
			project_slug: undefined,
			captured_at: "2026-06-01T00:00:00Z",
		});
		expect(claim.content_hash).toBe(contentHash("Luke likes coffee"));
		expect(claim.claim_id).toBe(
			deriveClaimId("pi", "profile/coffee.md", { kind: "whole" }, claim.content_hash),
		);
		// undefined optionals dropped, not stored as `undefined`
		expect("title" in claim).toBe(false);
		expect("project_slug" in claim).toBe(false);
		expect(claim.captured_at).toBe("2026-06-01T00:00:00Z");
	});

	it("makeClaim is idempotent — same input ⇒ same claim_id across calls", () => {
		const input = {
			source_store: "codex" as const,
			source_path: "MEMORY.md",
			span: { kind: "section" as const, start: 10, end: 40, heading: "Preferences" },
			scope_hint: "profile" as const,
			text: "## Preferences\nUse tmux for secrets",
		};
		expect(makeClaim(input).claim_id).toBe(makeClaim(input).claim_id);
	});
});

// ---------------------------------------------------------------------------

describe("migration/parse — frontmatter subset", () => {
	it("returns empty data + original body when no frontmatter", () => {
		const { data, body } = parseFrontmatter("just text\nno fm");
		expect(data).toEqual({});
		expect(body).toBe("just text\nno fm");
	});

	it("tolerates CRLF frontmatter delimiters", () => {
		const text = "---\r\nname: coffee\r\nscope: project\r\n---\r\nbody line\r\n";
		const { data, body } = parseFrontmatter(text);
		expect(data.name).toBe("coffee");
		expect(data.scope).toBe("project");
		expect(body).toBe("body line\r\n");
	});

	it("does not hoist keys out of a block-scalar body", () => {
		// the indented `type:`/`scope:` are block-scalar CONTENT, not real keys —
		// hoisting them would corrupt the scope hint downstream.
		const text = [
			"---",
			"name: x",
			"description: |",
			"  type: project",
			"  scope: reference",
			"real_key: yes",
			"---",
			"body",
		].join("\n");
		const { data } = parseFrontmatter(text);
		expect(data.name).toBe("x");
		expect(data.real_key).toBe("yes");
		expect(data.type).toBeUndefined();
		expect(data.scope).toBeUndefined();
	});

	it("parses flat scalars, quoted values, lists, and nested metadata", () => {
		const text = [
			"---",
			"name: coffee",
			'description: "Luke: likes coffee"',
			"source_event_ids:",
			"  - evt-1",
			"  - evt-2",
			"metadata:",
			"  node_type: fact",
			"  type: profile",
			"---",
			"body here",
		].join("\n");
		const { data, body } = parseFrontmatter(text);
		expect(data.name).toBe("coffee");
		expect(data.description).toBe("Luke: likes coffee");
		expect(data.source_event_ids).toEqual(["evt-1", "evt-2"]);
		expect(data.metadata).toEqual({ node_type: "fact", type: "profile" });
		expect(body).toBe("body here");
	});
});

describe("migration/parse — section chunking tiles the document", () => {
	const tile = (text: string, level: number) => {
		const sections = splitSections(text, level);
		// contiguous, gap-free, covering [0, len)
		expect(sections[0]!.start).toBe(0);
		expect(sections.at(-1)!.end).toBe(text.length);
		for (let i = 1; i < sections.length; i++) {
			expect(sections[i]!.start).toBe(sections[i - 1]!.end);
		}
		// every slice round-trips against the source text
		const rebuilt = sections.map((s) => text.slice(s.start, s.end)).join("");
		expect(rebuilt).toBe(text);
		return sections;
	};

	it("detects the shallowest heading level present", () => {
		expect(detectMinHeadingLevel("### deep\n## mid")).toBe(2);
		expect(detectMinHeadingLevel("no headings here")).toBeNull();
		expect(detectMinHeadingLevel("# top\n## mid")).toBe(1);
	});

	it("splits with a headingless preamble preserved as a section", () => {
		const text = "preamble line\n## A\nbody a\n## B\nbody b\n";
		const sections = tile(text, 2);
		expect(sections).toHaveLength(3);
		expect(sections[0]!.heading).toBeUndefined();
		expect(sections[1]!.heading).toBe("A");
		expect(sections[2]!.heading).toBe("B");
	});

	it("no preamble when the file opens with a heading", () => {
		const text = "## A\nbody a\n## B\nbody b\n";
		const sections = tile(text, 2);
		expect(sections).toHaveLength(2);
		expect(sections[0]!.heading).toBe("A");
	});

	it("returns the whole text as one section when no heading at the level", () => {
		const text = "### too deep\nbody\n";
		const sections = tile(text, 2);
		expect(sections).toHaveLength(1);
		expect(sections[0]!.text).toBe(text);
	});
});

