import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { mkdir, mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";

import {
	extractClaudeCode,
	extractCodex,
	extractObsidian,
	extractPi,
} from "../src/migration/extract/index.ts";
import { assembleLedger, runDryRun, writeLedger } from "../src/migration/dry-run.ts";
import type { StoreExtraction } from "../src/migration/ledger.ts";

// ---------------------------------------------------------------------------
// On-disk fixture helpers

let dir: string;

beforeEach(async () => {
	dir = await mkdtemp(join(tmpdir(), "p2a-extract-"));
});
afterEach(async () => {
	await rm(dir, { recursive: true, force: true });
});

async function put(rel: string, content: string): Promise<void> {
	const full = join(dir, rel);
	await mkdir(dirname(full), { recursive: true });
	await writeFile(full, content, "utf8");
}

/** The no-drops gate: every scanned file is a claim source or an explicit skip. */
function assertNoDrops(ex: StoreExtraction): void {
	const accounted = new Set([
		...ex.claims.map((c) => c.source_path),
		...ex.skipped.map((s) => s.path),
	]);
	const unaccounted = ex.files_seen.filter((f) => !accounted.has(f));
	expect(unaccounted).toEqual([]);
}

// ---------------------------------------------------------------------------

describe("extract/pi — whole-file claims with namespace-driven scope", () => {
	it("maps profile/project/daily/inbox and accounts for every file", async () => {
		await put("profile/coffee.md", "---\nname: coffee\ntype: profile\n---\nLuke likes coffee");
		await put("project/my-pi/goal.md", "---\nname: goal\n---\nShip P2");
		await put("daily/2026-06-01.md", "did a thing today");
		await put("inbox/note.md", "raw inbox note");
		await put("profile/empty.md", "   \n");
		// db/ is runtime state, outside the scanned subdirs
		await put("db/state.md", "should never be seen");

		const ex = await extractPi(dir);
		assertNoDrops(ex);

		const byPath = new Map(ex.claims.map((c) => [c.source_path, c]));
		expect(byPath.get("profile/coffee.md")!.scope_hint).toBe("profile");
		expect(byPath.get("project/my-pi/goal.md")!.scope_hint).toBe("project");
		expect(byPath.get("project/my-pi/goal.md")!.project_slug).toBe("my-pi");
		expect(byPath.get("daily/2026-06-01.md")!.scope_hint).toBe("episodic");
		expect(byPath.get("daily/2026-06-01.md")!.captured_at).toBe("2026-06-01T00:00:00Z");
		expect(byPath.get("inbox/note.md")!.scope_hint).toBe("inbox");

		// empty file skipped, not dropped; db/ never scanned
		expect(ex.skipped.map((s) => s.path)).toContain("profile/empty.md");
		expect(ex.files_seen).not.toContain("db/state.md");
	});
});

describe("extract/obsidian — legacy dream frontmatter", () => {
	it("reads scope + project slug + title, accounts for every file", async () => {
		await put(
			"project/my-pi/arch.md",
			"---\ntitle: Arch note\nscope: project\nlast_dreamed_at: 2026-05-01T00:00:00Z\n---\nbody",
		);
		await put("reference/links.md", "---\ntitle: Links\nscope: reference\n---\nbody");
		await put("blank.md", "");

		const ex = await extractObsidian(dir);
		assertNoDrops(ex);

		const byPath = new Map(ex.claims.map((c) => [c.source_path, c]));
		const arch = byPath.get("project/my-pi/arch.md")!;
		expect(arch.scope_hint).toBe("project");
		expect(arch.project_slug).toBe("my-pi");
		expect(arch.title).toBe("Arch note");
		expect(arch.captured_at).toBe("2026-05-01T00:00:00Z");
		expect(byPath.get("reference/links.md")!.scope_hint).toBe("reference");
		expect(ex.skipped.map((s) => s.path)).toContain("blank.md");
	});
});

describe("extract/claude-code — one fact per file, MEMORY.md is the index", () => {
	it("skips the generated index and reads nested metadata.type", async () => {
		await put("MEMORY.md", "# Memory Index\n- [x](x.md)");
		await put(
			"x.md",
			"---\nname: thing\ndescription: a thing\nmetadata:\n  node_type: fact\n  type: reference\n---\nbody",
		);

		const ex = await extractClaudeCode(dir);
		assertNoDrops(ex);

		const index = ex.skipped.find((s) => s.path === "MEMORY.md");
		expect(index?.reason).toMatch(/index/i);
		const claim = ex.claims.find((c) => c.source_path === "x.md")!;
		expect(claim.scope_hint).toBe("reference");
		expect(claim.title).toBe("thing");
	});
});

describe("extract/codex — heading-delimited sections tile each file", () => {
	it("chunks into gap-free section spans and hints scope from headings", async () => {
		const text = [
			"## Preferences",
			"Use tmux for secrets",
			"## Reusable knowledge",
			"Pi caches the system prompt",
			"## Task log",
			"Did a migration",
			"",
		].join("\n");
		await put("MEMORY.md", text);
		await put("empty.md", "\n\n");

		const ex = await extractCodex(dir);
		assertNoDrops(ex);

		const sections = ex.claims
			.filter((c) => c.source_path === "MEMORY.md")
			.sort((a, b) =>
				a.span.kind === "section" && b.span.kind === "section" ? a.span.start - b.span.start : 0,
			);
		expect(sections).toHaveLength(3);
		// spans are contiguous + gap-free and round-trip against the source
		for (let i = 0; i < sections.length; i++) {
			const span = sections[i]!.span;
			expect(span.kind).toBe("section");
			if (span.kind !== "section") continue;
			if (i > 0) {
				const prev = sections[i - 1]!.span;
				if (prev.kind === "section") expect(span.start).toBe(prev.end);
			}
			expect(text.slice(span.start, span.end)).toBe(sections[i]!.text);
		}
		expect(sections[0]!.scope_hint).toBe("profile"); // Preferences
		expect(sections[1]!.scope_hint).toBe("reference"); // Reusable knowledge
		expect(sections[2]!.scope_hint).toBe("episodic"); // Task log
		expect(ex.skipped.map((s) => s.path)).toContain("empty.md");
	});
});

// ---------------------------------------------------------------------------

describe("dry-run — coverage accounting + idempotency + read-only writeLedger", () => {
	async function seedAllStores() {
		const piRoot = join(dir, "pi");
		const obsRoot = join(dir, "obsidian");
		const ccRoot = join(dir, "cc");
		const codexRoot = join(dir, "codex");
		await mkdir(piRoot, { recursive: true });
		await mkdir(join(piRoot, "profile"), { recursive: true });
		await writeFile(join(piRoot, "profile", "a.md"), "---\nname: a\n---\nfact a", "utf8");
		await mkdir(obsRoot, { recursive: true });
		await writeFile(join(obsRoot, "b.md"), "---\ntitle: b\nscope: reference\n---\nfact b", "utf8");
		await mkdir(ccRoot, { recursive: true });
		await writeFile(join(ccRoot, "MEMORY.md"), "# index", "utf8");
		await writeFile(join(ccRoot, "c.md"), "---\nname: c\n---\nfact c", "utf8");
		await mkdir(codexRoot, { recursive: true });
		await writeFile(join(codexRoot, "MEMORY.md"), "## S1\nx\n## S2\ny\n", "utf8");
		return { pi: piRoot, obsidian: obsRoot, "claude-code": ccRoot, codex: codexRoot };
	}

	it("reports complete coverage with no unaccounted files", async () => {
		const roots = await seedAllStores();
		const result = await runDryRun(roots, { now: "2026-06-23T00:00:00Z" });

		expect(result.complete).toBe(true);
		for (const cov of result.coverage) expect(cov.unaccounted).toEqual([]);
		expect(result.manifest.version).toBe(1);
		expect(result.manifest.generated_at).toBe("2026-06-23T00:00:00Z");
		expect(result.manifest.total_claims).toBe(result.claims.length);
		// pi(1) + obsidian(1) + cc(1, MEMORY.md skipped) + codex(2 sections) = 5
		expect(result.claims).toHaveLength(5);
	});

	it("flags unaccounted files via assembleLedger (a silent drop fails the gate)", () => {
		const bad: StoreExtraction = {
			source_store: "pi",
			root: "/x",
			files_seen: ["a.md", "ghost.md"],
			claims: [],
			skipped: [{ source_store: "pi", path: "a.md", reason: "empty file" }],
		};
		const result = assembleLedger([bad], "2026-06-23T00:00:00Z");
		expect(result.complete).toBe(false);
		expect(result.coverage[0]!.unaccounted).toEqual(["ghost.md"]);
	});

	it("is idempotent — claim ids are identical across two runs", async () => {
		const roots = await seedAllStores();
		const r1 = await runDryRun(roots, { now: "2026-06-23T00:00:00Z" });
		const r2 = await runDryRun(roots, { now: "2026-06-23T00:00:00Z" });
		const ids = (r: typeof r1) => r.claims.map((c) => c.claim_id).sort();
		expect(ids(r1)).toEqual(ids(r2));
	});

	it("writeLedger writes only to the workdir (never a source store)", async () => {
		const roots = await seedAllStores();
		const result = await runDryRun(roots, { now: "2026-06-23T00:00:00Z" });
		const workdir = join(dir, "ledger-out");
		const { manifestPath, claimsPath } = await writeLedger(workdir, result);

		const { readFile } = await import("node:fs/promises");
		const manifest = JSON.parse(await readFile(manifestPath, "utf8"));
		expect(manifest.total_claims).toBe(result.claims.length);
		const lines = (await readFile(claimsPath, "utf8")).trimEnd().split("\n");
		expect(lines).toHaveLength(result.claims.length);
		// every emitted line is a parseable claim with a derived id
		for (const line of lines) expect(JSON.parse(line).claim_id).toHaveLength(32);
	});
});

