/**
 * Embedding client for resident sidecar models.
 *
 * Speaks to whatever `DREAM_EMBED_URL` resolves to — default is the local MLX
 * embedder on `http://127.0.0.1:8186/v1/embeddings`. Default wire shape is
 * OpenAI-compatible: `{ model, input: string[] }` → `{ data: [{ index, embedding }] }`.
 * Set `DREAM_EMBED_API=tei` for TEI `/embed` fallback endpoints:
 * `{ inputs: string[] }` → `number[][]`.
 *
 * Prompt templating:
 *   Qwen3-Embedding-0.6B expects an instruction prefix on queries but raw text
 *   on documents (per the model card). We apply the templates client-side so
 *   the embedder stays agnostic. The exact template strings are hashed into
 *   `promptHash()` — any change invalidates the index and forces a reindex,
 *   which is the correctness contract we want.
 */

import { createHash } from "node:crypto";

const DEFAULT_QUERY_TEMPLATE =
	"Instruct: Given a web search query, retrieve relevant passages that answer the query\nQuery: {q}";
const DEFAULT_DOC_TEMPLATE = "{d}";
const DEFAULT_VERSION = "v1";

export type EmbedKind = "query" | "document";
export type EmbedApi = "tei" | "openai";

export type EmbedConfig = {
	url: string;
	api: EmbedApi;
	model: string;
	batchSize: number;
	timeoutMs: number;
	queryTemplate: string;
	docTemplate: string;
	promptVersion: string;
};

export function loadEmbedConfig(): EmbedConfig {
	return {
		url: process.env.DREAM_EMBED_URL ?? "http://127.0.0.1:8186/v1/embeddings",
		api: parseEmbedApi(process.env.DREAM_EMBED_API),
		model:
			process.env.DREAM_EMBED_MODEL ?? "mlx-community/Qwen3-Embedding-0.6B-4bit-DWQ",
		batchSize: Number(process.env.DREAM_EMBED_BATCH ?? 32),
		timeoutMs: Number(process.env.DREAM_EMBED_TIMEOUT_MS ?? 30_000),
		queryTemplate: process.env.DREAM_EMBED_QUERY_TEMPLATE ?? DEFAULT_QUERY_TEMPLATE,
		docTemplate: process.env.DREAM_EMBED_DOC_TEMPLATE ?? DEFAULT_DOC_TEMPLATE,
		promptVersion: process.env.DREAM_EMBED_PROMPT_VERSION ?? DEFAULT_VERSION,
	};
}

function parseEmbedApi(raw: string | undefined): EmbedApi {
	if (!raw || raw === "openai") return "openai";
	if (raw === "tei") return "tei";
	throw new Error(`unsupported DREAM_EMBED_API=${raw}; expected tei or openai`);
}

/** Stable hash over the prompt policy. Bump to invalidate the index. */
export function promptHash(cfg: EmbedConfig): string {
	const payload = JSON.stringify({
		query: cfg.queryTemplate,
		doc: cfg.docTemplate,
		version: cfg.promptVersion,
	});
	return createHash("sha256").update(payload).digest("hex").slice(0, 16);
}

function applyTemplate(text: string, kind: EmbedKind, cfg: EmbedConfig): string {
	const tpl = kind === "query" ? cfg.queryTemplate : cfg.docTemplate;
	return tpl.replace(kind === "query" ? "{q}" : "{d}", text);
}

function embedRequestBody(inputs: string[], cfg: EmbedConfig): unknown {
	if (cfg.api === "openai") return { model: cfg.model, input: inputs };
	return { inputs };
}

/**
 * Embed an array of texts. Batches at `cfg.batchSize`. Returns vectors in
 * input order. Throws on any HTTP/parse failure — caller is the boundary.
 */
export async function embedBatch(
	texts: string[],
	kind: EmbedKind,
	cfg: EmbedConfig,
): Promise<number[][]> {
	if (texts.length === 0) return [];
	const out: number[][] = [];
	for (let i = 0; i < texts.length; i += cfg.batchSize) {
		const slice = texts.slice(i, i + cfg.batchSize).map((t) => applyTemplate(t, kind, cfg));
		const batch = await embedOnce(slice, cfg);
		out.push(...batch);
	}
	return out;
}

async function embedOnce(inputs: string[], cfg: EmbedConfig): Promise<number[][]> {
	const ctrl = new AbortController();
	const timer = setTimeout(() => ctrl.abort(), cfg.timeoutMs);
	try {
		const resp = await fetch(cfg.url, {
			method: "POST",
			headers: { "Content-Type": "application/json" },
			body: JSON.stringify(embedRequestBody(inputs, cfg)),
			signal: ctrl.signal,
		});
		if (!resp.ok) {
			const body = await resp.text().catch(() => "");
			throw new Error(`embed HTTP ${resp.status}: ${body.slice(0, 300)}`);
		}
		return parseEmbedResponse(await resp.json(), cfg.api);
	} finally {
		clearTimeout(timer);
	}
}

export function parseEmbedResponse(data: unknown, api: EmbedApi): number[][] {
	if (api === "tei") return parseTeiResponse(data);
	return parseOpenAiResponse(data);
}

function parseTeiResponse(data: unknown): number[][] {
	if (Array.isArray(data) && data.every(isNumberArray)) return data;
	throw new Error("embed response shape mismatch (expected TEI number[][])");
}

function parseOpenAiResponse(data: unknown): number[][] {
	if (!isRecord(data) || !Array.isArray(data.data)) {
		throw new Error("embed response shape mismatch (expected OpenAI { data: [...] })");
	}
	const rows = data.data;
	if (!rows.every(isOpenAiEmbeddingRow)) {
		throw new Error("embed response shape mismatch (expected OpenAI embedding rows)");
	}
	const hasIndexes = rows.every((row) => typeof row.index === "number");
	const ordered = hasIndexes
		? [...rows].sort((a, b) => (a.index as number) - (b.index as number))
		: rows;
	return ordered.map((row) => row.embedding);
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null;
}

function isNumberArray(value: unknown): value is number[] {
	return Array.isArray(value) && value.every((n) => typeof n === "number");
}

function isOpenAiEmbeddingRow(value: unknown): value is { index?: number; embedding: number[] } {
	return isRecord(value) && isNumberArray(value.embedding);
}

/**
 * Probe the embedder once for the vector dim. Used at boot to validate the
 * index dim matches what the embedder produces.
 */
export async function probeDim(cfg: EmbedConfig): Promise<number> {
	const vec = await embedOnce(["warmup"], cfg);
	const first = vec[0];
	if (!first || first.length === 0) throw new Error("embedder returned empty vector");
	return first.length;
}

