export type PiCompleteFn = (
	model: PiModelLike,
	context: {
		systemPrompt?: string;
		messages: Array<{ role: "user" | "assistant" | "toolResult"; content: unknown; timestamp: number }>;
		tools?: unknown[];
	},
	options?: {
		apiKey?: string;
		headers?: Record<string, string>;
		signal?: AbortSignal;
		maxTokens?: number;
		timeoutMs?: number;
		/** Pi-ai cache retention; "none" disables cache_control writes (saves 25% surcharge). */
		cacheRetention?: "none" | "short" | "long";
		sessionId?: string;
	},
) => Promise<{
	content: Array<{ type: string; text?: string }>;
	usage: {
		input: number;
		output: number;
		cacheRead: number;
		cacheWrite: number;
		totalTokens: number;
		cost?: { total?: number };
	};
	stopReason: "stop" | "length" | "toolUse" | "error" | "aborted";
	errorMessage?: string;
}>;

export type PiAuthResolver = Pick<PiModelRegistryLike, "getApiKeyAndHeaders">;
export type PiModelRegistry = Pick<
	PiModelRegistryLike,
	"getApiKeyAndHeaders" | "getAvailable" | "find"
>;

export interface PiModelCallOptions {
	registry: PiAuthResolver;
	model: PiModelLike;
	system?: string;
	prompt: string;
	maxTokens?: number;
	signal?: AbortSignal;
	/**
	 * Pi-ai cache retention. "none" disables prompt-cache writes — use when
	 * batches don't share a stable prefix, to avoid paying the 25% cache-write
	 * surcharge for cache slots that will never be read.
	 */
	cacheRetention?: "none" | "short" | "long";
	/** Stable session affinity for providers that support prompt-cache/session reuse. */
	sessionId?: string;
	/** Test injection. Defaults to dynamic-importing `@valkyriweb/pi-ai`. */
	completeFn?: PiCompleteFn;
}

export interface PiModelCallResult {
	text: string;
	usage: {
		input: number;
		output: number;
		cacheRead: number;
		cacheWrite: number;
		total: number;
		costUsd?: number;
	};
	model: { provider: string; id: string };
	latencyMs: number;
	stopReason: "stop" | "length";
}

// ---------------------------------------------------------------------------
// Lazy load of @valkyriweb/pi-ai — keeps unit tests from pulling in
// the provider transitive deps when they inject `completeFn`.

let _completeCache: PiCompleteFn | null = null;
async function loadComplete(): Promise<PiCompleteFn> {
	if (_completeCache) return _completeCache;
	const mod = (await import("@valkyriweb/pi-ai")) as { complete: unknown };
	if (typeof mod.complete !== "function") {
		throw new PiModelError("@valkyriweb/pi-ai did not export `complete`");
	}
	_completeCache = mod.complete as PiCompleteFn;
	return _completeCache;
}

