 * the identity `{d}` (per the model card), so reconcile needs no query prefix.
 */

import type { Embedder } from "./types.ts";

/** Cosine similarity of two equal-rank vectors. Returns 0 if either is zero. */
export function cosine(a: number[], b: number[]): number {
	const n = Math.min(a.length, b.length);
	let dot = 0;
	let na = 0;
	let nb = 0;
	for (let i = 0; i < n; i++) {
		const ai = a[i] ?? 0;
		const bi = b[i] ?? 0;
		dot += ai * bi;
		na += ai * ai;
		nb += bi * bi;
	}
	if (na === 0 || nb === 0) return 0;
