/**
 * Candidate-cluster generation (ADR 0009 D2): embedding similarity *generates
 * clusters only* — it never decides merge/supersede. The judge does that.
 *
 * Items are blocked by `scope` first (a fact under a different scope is a
 * different fact until proven otherwise — and blocking keeps the pairwise
 * comparison cheap). Within a block, any two items with cosine ≥ `threshold` are
 * connected; clusters are the connected components. Only components with ≥2
 * members are returned — singletons need no judging.
 *
 * Limitation (intentional, per ADR 0009): a fact captured under *different*
 * scope hints across stores will not cluster here. The scope mismatch is itself
 * a signal; cross-scope reconciliation is out of P2b scope.
 */

import { cosine } from "./embedder.ts";
import type { Cluster, ReconcileInput } from "./types.ts";

/** Group items into candidate clusters. `vectors[i]` must align with `items[i]`.
 * Returns only multi-member clusters, members preserving input order. */
export function clusterBySimilarity(
	items: ReconcileInput[],
	vectors: number[][],
	threshold: number,
): Cluster[] {
	if (items.length !== vectors.length) {
		throw new Error(
			`clusterBySimilarity: ${items.length} items but ${vectors.length} vectors`,
		);
	}

	// Block indices by scope.
	const blocks = new Map<string, number[]>();
	for (let i = 0; i < items.length; i++) {
		const scope = items[i]?.scope ?? "";
		const block = blocks.get(scope);
		if (block) block.push(i);
		else blocks.set(scope, [i]);
	}

	const parent = new Array(items.length).fill(0).map((_, i) => i);
	const find = (x: number): number => {
		let root = x;
		while (parent[root] !== root) root = parent[root] as number;
		// Path compression.
		let cur = x;
		while (parent[cur] !== root) {
			const next = parent[cur] as number;
			parent[cur] = root;
			cur = next;
		}
		return root;
	};
	const union = (a: number, b: number): void => {
		const ra = find(a);
		const rb = find(b);
		if (ra !== rb) parent[rb] = ra;
	};

	// Connect near-duplicate pairs within each block.
	for (const idxs of blocks.values()) {
		for (let p = 0; p < idxs.length; p++) {
			for (let q = p + 1; q < idxs.length; q++) {
				const i = idxs[p] as number;
				const j = idxs[q] as number;
				if (cosine(vectors[i] as number[], vectors[j] as number[]) >= threshold) {
					union(i, j);
				}
			}
		}
	}

	// Gather connected components, preserving input order within each.
	const components = new Map<number, number[]>();
	for (let i = 0; i < items.length; i++) {
		const root = find(i);
		const comp = components.get(root);
		if (comp) comp.push(i);
		else components.set(root, [i]);
	}

	const clusters: Cluster[] = [];
	for (const member of components.values()) {
		if (member.length < 2) continue;
		const first = items[member[0] as number] as ReconcileInput;
		clusters.push({
			scope: first.scope,
			member_ids: member.map((i) => (items[i] as ReconcileInput).id),
		});
	}
	return clusters;
}

