 * (`reconcileOne`). Pure types + zod schemas, no IO.
 *
 * Two non-destructive verbs: `merge` (parallel captures of one fact → one
 * canonical record citing all sources) and `supersede` (a new claim corrects an
 * older one; the old is retained but flagged). `novel` keeps a claim as-is.
 * Nothing here ever deletes — the judge proposes; a human gate applies.
 */

import { z } from "zod";

/** The minimal claim shape the reconciler needs — deliberately decoupled from
 * migration's `Claim` so the ingestion path (an `inbox/` event) can map onto the
 * same core. `scope` is the blocking key; `content_hash` is the exact-dup key. */
export type ReconcileInput = {
	id: string;
	text: string;
	content_hash: string;
	scope: string;
	title?: string | undefined;
	/** Provenance label (e.g. source store / harness), surfaced to the judge. */
	source?: string | undefined;
};

// ---------------------------------------------------------------------------
// Decisions — the reconciler's output, one per resolved claim/group.

export const DecisionSchema = z.discriminatedUnion("verb", [
	/** Keep the claim as its own canonical record. */
	z.object({ verb: z.literal("novel"), id: z.string().min(1) }),
	/** Parallel captures of one fact: collapse into `canonical_id`, recording
	 * every member as provenance. `basis` distinguishes exact-hash from judge. */
	z.object({
		verb: z.literal("merge"),
		canonical_id: z.string().min(1),
		member_ids: z.array(z.string().min(1)).min(2),
		basis: z.enum(["exact_hash", "judge"]),
		rationale: z.string().min(1),
	}),
	/** Temporal correction: `new_id` supersedes `superseded_id`. The superseded
	 * record is retained (status flips at apply) but drops out of active recall. */
	z.object({
		verb: z.literal("supersede"),
		new_id: z.string().min(1),
		superseded_id: z.string().min(1),
		rationale: z.string().min(1),
	}),
]);
export type Decision = z.infer<typeof DecisionSchema>;

// ---------------------------------------------------------------------------
// Judge IO — the LLM proposes relations within a candidate cluster.

/** One related group the judge found inside a cluster. `relation: "duplicate"`
 * ⇒ all members state the same fact, keep `canonical_id`. `relation:
 * "supersedes"` ⇒ `canonical_id` is the newer/correcting claim; the other
 * members it supersedes. Members of the cluster absent from every group are
 * distinct (→ novel). */
export const JudgeGroupSchema = z.object({
	member_ids: z.array(z.string().min(1)).min(2),
	relation: z.enum(["duplicate", "supersedes"]),
	canonical_id: z.string().min(1),
	rationale: z.string().min(1),
});
export const JudgeOutputSchema = z.object({
	groups: z.array(JudgeGroupSchema).default([]),
});
export type JudgeOutput = z.infer<typeof JudgeOutputSchema>;

// ---------------------------------------------------------------------------
// Injected seams (tests stub these; production wires the real services).

export type Embedder = { embed(texts: string[]): Promise<number[][]> };
export type Judge = (cluster: ReconcileInput[]) => Promise<JudgeOutput>;

export type Cluster = { scope: string; member_ids: string[] };

export type ReconcileStats = {
	inputs: number;
	exact_dup_groups: number;
	clusters_judged: number;
	merges: number;
	supersedes: number;
	novel: number;
};

export type ReconcileResult = {
	decisions: Decision[];
	clusters: Cluster[];
	stats: ReconcileStats;
};

input.content:
/**
 * The shared reconciliation core (ADR 0009 D1). One translation of
 * embedding-cluster → exact/judge authority → {novel|merge|supersede}, called
 * two ways:
 *   - `reconcileBulk` — the one-off migration over the whole claim ledger.
 *   - `reconcileOne`  — ongoing dream consolidation, one promoted claim vs the
 *     existing corpus (wired in a later phase; here to prove the core is shared,
 *     not migration-only).
 *
 * Both run the SAME exact-hash check, the SAME judge, and the SAME group→decision
 * mapping. Nothing here writes to disk or deletes — it returns proposals; a human
 * gate applies them (ADR 0009 D6).
 */

import { cosine } from "./embedder.ts";
import { clusterBySimilarity } from "./cluster.ts";
import type {
	Cluster,
	Decision,
	Embedder,
	Judge,
	JudgeOutput,
	ReconcileInput,
	ReconcileResult,
	ReconcileStats,
} from "./types.ts";

export const DEFAULT_SIM_THRESHOLD = 0.83;
const DEFAULT_TOP_K = 8;

export type ReconcileDeps = {
	embedder: Embedder;
	judge: Judge;
	/** Cosine cut-off for candidate clustering. Higher = fewer, tighter clusters. */
	threshold?: number;
};

/**
 * Reconcile a whole ledger of claims. Exact-content duplicates collapse first
 * (cheap, deterministic); the survivors are embedded, scope-blocked, clustered,
 * and each multi-member cluster is sent to the judge.
 */
export async function reconcileBulk(
	inputs: ReconcileInput[],
	deps: ReconcileDeps,
): Promise<ReconcileResult> {
	const threshold = deps.threshold ?? DEFAULT_SIM_THRESHOLD;
	const decisions: Decision[] = [];
	let exactDupGroups = 0;

	// 1. Collapse exact-content duplicates into representatives. (The real corpus
	//    has zero of these cross-store, but ingestion hits them constantly, and
	//    it's a free, deterministic pre-pass.)
	const byHash = new Map<string, ReconcileInput[]>();
	for (const input of inputs) {
		const group = byHash.get(input.content_hash);
		if (group) group.push(input);
		else byHash.set(input.content_hash, [input]);
	}
	const representatives: ReconcileInput[] = [];
	for (const group of byHash.values()) {
		const sorted = [...group].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
		const canonical = sorted[0] as ReconcileInput;
		representatives.push(canonical);
		if (sorted.length > 1) {
			exactDupGroups++;
			decisions.push({
				verb: "merge",
				canonical_id: canonical.id,
				member_ids: sorted.map((c) => c.id),
				basis: "exact_hash",
				rationale: "identical normalised content",
			});
		}
	}

	// 2. Embed + cluster the representatives.
	const vectors = await deps.embedder.embed(representatives.map((r) => r.text));
	const clusters = clusterBySimilarity(representatives, vectors, threshold);
	const byId = new Map(representatives.map((r) => [r.id, r] as const));

	// 3. Judge each multi-member cluster; map its groups to decisions.
	const decided = new Set<string>();
	let clustersJudged = 0;
	let judgeFailures = 0;
	for (const cluster of clusters) {
		const members = cluster.member_ids
			.map((id) => byId.get(id))
			.filter((m): m is ReconcileInput => m !== undefined);
		const idSet = new Set(members.map((m) => m.id));
		let output: JudgeOutput;
		try {
			output = await deps.judge(members);
			clustersJudged++;
		} catch {
			// Conservative: leave the whole cluster's members to fall through to
			// `novel` and surface the failure in stats (ADR 0009 D2 — never drop).
			judgeFailures++;
			continue;
		}
		for (const group of output.groups) {
			decisions.push(...groupToDecisions(group, idSet, decided));
		}
	}

	// 4. Every representative without a phase-3 disposition is novel.
	for (const rep of representatives) {
		if (!decided.has(rep.id)) decisions.push({ verb: "novel", id: rep.id });
	}

	return { decisions, clusters, stats: tally(inputs.length, exactDupGroups, clustersJudged, judgeFailures, decisions) };
}

export type ReconcileOneDeps = ReconcileDeps & { topK?: number };
export type CorpusEntry = { input: ReconcileInput; vector: number[] };

/**
 * Reconcile a single candidate against an already-embedded corpus. The ingestion
 * (dream-consolidation) entry point — same authority order as bulk: exact hash,
 * then judge over the nearest same-scope neighbours. Returns one decision.
 */
export async function reconcileOne(
	candidate: ReconcileInput,
	corpus: CorpusEntry[],
	deps: ReconcileOneDeps,
): Promise<Decision> {
	const threshold = deps.threshold ?? DEFAULT_SIM_THRESHOLD;
	const topK = deps.topK ?? DEFAULT_TOP_K;

	const exact = corpus.find((e) => e.input.content_hash === candidate.content_hash);
	if (exact) {
		return {
			verb: "merge",
			canonical_id: exact.input.id,
			member_ids: [exact.input.id, candidate.id],
			basis: "exact_hash",
			rationale: "identical normalised content",
		};
	}

	const [vec] = await deps.embedder.embed([candidate.text]);
	if (!vec) return { verb: "novel", id: candidate.id };

	const neighbours = corpus
		.filter((e) => e.input.scope === candidate.scope)
		.map((e) => ({ entry: e, sim: cosine(vec, e.vector) }))
		.filter((n) => n.sim >= threshold)
		.sort((a, b) => b.sim - a.sim)
		.slice(0, topK)
		.map((n) => n.entry.input);

	if (neighbours.length === 0) return { verb: "novel", id: candidate.id };

	const members = [candidate, ...neighbours];
	const idSet = new Set(members.map((m) => m.id));
	let output: JudgeOutput;
	try {
		output = await deps.judge(members);
	} catch {
		return { verb: "novel", id: candidate.id };
	}

	const group = output.groups.find((g) => isUsable(g, idSet) && g.member_ids.includes(candidate.id));
	if (!group) return { verb: "novel", id: candidate.id };
	const [decision] = groupToDecisions(group, idSet, new Set());
	return decision ?? { verb: "novel", id: candidate.id };
}

// ---------------------------------------------------------------------------
// Shared group → decision translation. Used by both callers so merge/supersede
// semantics can never drift between migration and ingestion.

/** A judge group is usable only if its ids are real and its canonical is among
 * them — defends against model hallucination. */
function isUsable(group: JudgeOutput["groups"][number], idSet: Set<string>): boolean {
	if (!group.member_ids.includes(group.canonical_id)) return false;
	return group.member_ids.every((id) => idSet.has(id));
}

/** Translate one judge group into decisions, marking touched ids in `decided`.
 * Members already decided (by an earlier group in the same cluster) are skipped
 * so a hallucinated overlap can't double-dispose a claim. */
function groupToDecisions(
	group: JudgeOutput["groups"][number],
	idSet: Set<string>,
	decided: Set<string>,
): Decision[] {
	if (!isUsable(group, idSet)) return [];
	const members = group.member_ids.filter((id) => !decided.has(id));
	if (!members.includes(group.canonical_id) || members.length < 2) return [];

	if (group.relation === "duplicate") {
		for (const id of members) decided.add(id);
		return [
			{
				verb: "merge",
				canonical_id: group.canonical_id,
				member_ids: members,
				basis: "judge",
				rationale: group.rationale,
			},
		];
	}

	// supersedes: canonical is the newer claim; the rest are superseded by it.
	const out: Decision[] = [];
	decided.add(group.canonical_id);
	for (const id of members) {
		if (id === group.canonical_id) continue;
		decided.add(id);
		out.push({
			verb: "supersede",
			new_id: group.canonical_id,
			superseded_id: id,
			rationale: group.rationale,
		});
	}
	return out;
}

function tally(
	inputs: number,
	exactDupGroups: number,
	clustersJudged: number,
	judgeFailures: number,
	decisions: Decision[],
): ReconcileStats {
	let merges = 0;
	let supersedes = 0;
	let novel = 0;
	for (const d of decisions) {
		if (d.verb === "merge") merges++;
		else if (d.verb === "supersede") supersedes++;
		else novel++;
	}
	return {
		inputs,
		exact_dup_groups: exactDupGroups,
		clusters_judged: clustersJudged,
		judge_failures: judgeFailures,
		merges,
		supersedes,
		novel,
	};
}

