/**
 * Migration's reconcile caller (P2b, ADR 0009). Bridges the read-only claim
 * ledger (P2a) to the shared reconcile core: filter scaffolding → quarantine
 * (D7), map the survivors to `ReconcileInput`, run `reconcileBulk`, and assemble
 * a `ReconciliationManifest` — the artifact Luke signs off before any apply (D6).
 *
 * The "no claim lost" guarantee from P2a carries through here at the claim level:
 * every input claim must land in exactly one of {quarantined, a decision}.
 * `accountReconciliation` proves it; `complete: false` blocks sign-off.
 *
 * Pure (claims in, manifest out; seams injected) so it runs in CI without a live
 * embedder or judge. Live wiring lives in the CLI.
 */

import { z } from "zod";
import { CLAIM_SOURCE_STORES, type Claim } from "./ledger.ts";
import { reconcileBulk, type ReconcileDeps } from "../reconcile/reconcile.ts";
import {
	DecisionSchema,
	ReconcileStatsSchema,
	type Decision,
	type ReconcileInput,
} from "../reconcile/types.ts";

/** Codex episodic transcript scaffolding — repeating template section headings
 * that carry no fact. ~1,050 fragments in the real corpus (survey 2026-06-23).
 * Matched case-insensitively on the section heading. */
export const CODEX_BOILERPLATE_HEADINGS = new Set(
	["memory summary", "recording summary", "citations"].map((h) => h),
);

/** Claims larger than this are scaffolding-shaped blobs (e.g. the 446 KB
 * single-section codex dump), not atomic facts — quarantine rather than embed. */
export const DEFAULT_MAX_CLAIM_BYTES = 50_000;

export type ScaffoldingOptions = {
	maxClaimBytes?: number;
};

/** Decide whether a claim is scaffolding (→ quarantine) rather than a fact.
 * Returns the quarantine reason, or null to keep. */
export function scaffoldingReason(claim: Claim, options: ScaffoldingOptions = {}): string | null {
	const maxBytes = options.maxClaimBytes ?? DEFAULT_MAX_CLAIM_BYTES;
	const bytes = Buffer.byteLength(claim.text, "utf8");
	if (bytes > maxBytes) return `oversized (${bytes} bytes > ${maxBytes})`;
	if (
		claim.source_store === "codex" &&
		claim.span.kind === "section" &&
		claim.span.heading &&
		CODEX_BOILERPLATE_HEADINGS.has(claim.span.heading.trim().toLowerCase())
	) {
		return `codex boilerplate section "${claim.span.heading}"`;
	}
	return null;
}

/** Map a ledger claim onto the source-agnostic reconcile shape. Scope is blocked
 * by hint, narrowed by project so cross-project facts don't cluster together. */
export function claimToReconcileInput(claim: Claim): ReconcileInput {
	const scope = claim.project_slug ? `${claim.scope_hint}/${claim.project_slug}` : claim.scope_hint;
	const input: ReconcileInput = {
		id: claim.claim_id,
		text: claim.text,
		content_hash: claim.content_hash,
		scope,
		source: claim.source_store,
	};
	if (claim.title !== undefined) input.title = claim.title;
	return input;
}

export const QuarantineEntrySchema = z.object({
	claim_id: z.string().min(1),
	source_store: z.enum(CLAIM_SOURCE_STORES),
	source_path: z.string().min(1),
	reason: z.string().min(1),
	bytes: z.number().int().nonnegative(),
});
export type QuarantineEntry = z.infer<typeof QuarantineEntrySchema>;

export const ReconciliationManifestSchema = z.object({
	version: z.literal(1),
	generated_at: z.string().min(1),
	threshold: z.number(),
	total_claims: z.number().int().nonnegative(),
	eligible_claims: z.number().int().nonnegative(),
	stats: ReconcileStatsSchema,
	quarantined: z.array(QuarantineEntrySchema),
	decisions: z.array(DecisionSchema),
	/** True iff every input claim is accounted for (quarantined ∪ decided). */
	complete: z.boolean(),
	/** Claim ids that fell through every disposition — a silent-drop bug. Empty
	 * when `complete`. */
	unaccounted: z.array(z.string()),
});
export type ReconciliationManifest = z.infer<typeof ReconciliationManifestSchema>;

/** Partition claims into reconcile-eligible facts and quarantined scaffolding. */
export function partitionClaims(
	claims: Claim[],
	options: ScaffoldingOptions = {},
): { eligible: Claim[]; quarantined: QuarantineEntry[] } {
	const eligible: Claim[] = [];
	const quarantined: QuarantineEntry[] = [];
	for (const claim of claims) {
		const reason = scaffoldingReason(claim, options);
		if (reason === null) {
			eligible.push(claim);
		} else {
			quarantined.push({
				claim_id: claim.claim_id,
				source_store: claim.source_store,
				source_path: claim.source_path,
				reason,
				bytes: Buffer.byteLength(claim.text, "utf8"),
			});
		}
	}
	return { eligible, quarantined };
}

/** Every claim_id touched by a decision (covered = not dropped). */
function decidedIds(decisions: Decision[]): Set<string> {
	const ids = new Set<string>();
	for (const d of decisions) {
		if (d.verb === "novel") ids.add(d.id);
		else if (d.verb === "merge") for (const m of d.member_ids) ids.add(m);
		else {
			ids.add(d.new_id);
			ids.add(d.superseded_id);
		}
	}
	return ids;
}

/** Claim-level no-drops check: quarantined ∪ decided must equal the input set. */
export function accountReconciliation(
	claims: Claim[],
	quarantined: QuarantineEntry[],
	decisions: Decision[],
): { complete: boolean; unaccounted: string[] } {
	const accounted = decidedIds(decisions);
	for (const q of quarantined) accounted.add(q.claim_id);
	const unaccounted = claims.map((c) => c.claim_id).filter((id) => !accounted.has(id));
	return { complete: unaccounted.length === 0, unaccounted };
}

export type ReconcileLedgerOptions = ScaffoldingOptions & {
	/** ISO timestamp; injected so the function stays pure/testable. */
	generatedAt: string;
};

/** Run the full migration reconciliation and assemble the sign-off manifest. */
export async function reconcileLedger(
	claims: Claim[],
	deps: ReconcileDeps,
	options: ReconcileLedgerOptions,
): Promise<ReconciliationManifest> {
	const { eligible, quarantined } = partitionClaims(claims, options);
	const result = await reconcileBulk(eligible.map(claimToReconcileInput), deps);
	const { complete, unaccounted } = accountReconciliation(claims, quarantined, result.decisions);
	return ReconciliationManifestSchema.parse({
		version: 1,
		generated_at: options.generatedAt,
		threshold: deps.threshold ?? 0.83,
		total_claims: claims.length,
		eligible_claims: eligible.length,
		stats: result.stats,
		quarantined,
		decisions: result.decisions,
		complete,
		unaccounted,
	});
}

