 * no raw claim is dropped. */
function groupToDecisions(
	group: JudgeOutput["groups"][number],
	idSet: Set<string>,
	decided: Set<string>,
	expand: Expander,
): Decision[] {
	if (!isUsable(group, idSet)) return [];
	const reps = group.member_ids.filter((id) => !decided.has(id));
	if (!reps.includes(group.canonical_id) || reps.length < 2) return [];

	if (group.relation === "duplicate") {
		for (const id of reps) decided.add(id);
		return [
			{
				verb: "merge",
				canonical_id: group.canonical_id,
				member_ids: expand(reps),
				basis: "judge",
				rationale: group.rationale,
			},
		];
	}

	// supersedes: canonical is the newer claim; the rest are superseded by it.
	// Each side's exact-hash duplicates are folded in so they aren't dropped.
