import { describe, expect, it } from "vitest";

import { cosine } from "../src/reconcile/embedder.ts";
import { clusterBySimilarity } from "../src/reconcile/cluster.ts";
import { buildJudgePrompt, parseJudgeOutput } from "../src/reconcile/judge.ts";
import { reconcileBulk, reconcileOne, type CorpusEntry } from "../src/reconcile/reconcile.ts";
import type { Embedder, Judge, JudgeOutput, ReconcileInput } from "../src/reconcile/types.ts";

// ---------------------------------------------------------------------------
// Helpers

function input(id: string, over: Partial<ReconcileInput> = {}): ReconcileInput {
	return {
		id,
		text: over.text ?? `text-${id}`,
		content_hash: over.content_hash ?? `hash-${id}`,
		scope: over.scope ?? "project",
		...(over.title !== undefined ? { title: over.title } : {}),
		...(over.source !== undefined ? { source: over.source } : {}),
	};
}

/** Embedder that returns a fixed vector per text; unknown text → orthogonal-ish. */
function fixedEmbedder(byText: Record<string, number[]>): Embedder {
	let n = 0;
	return {
		embed: async (texts) =>
			texts.map((t) => byText[t] ?? [0, 0, ++n /* unique → far from everything */]),
	};
}

/** Judge that returns a canned output regardless of input. */
function cannedJudge(output: JudgeOutput): Judge {
	return async () => output;
}

// ---------------------------------------------------------------------------

describe("reconcile/embedder — cosine", () => {
	it("is 1 for identical, 0 for orthogonal, 0 for a zero vector", () => {
		expect(cosine([1, 2, 3], [1, 2, 3])).toBeCloseTo(1);
		expect(cosine([1, 0], [0, 1])).toBe(0);
		expect(cosine([0, 0], [1, 1])).toBe(0);
	});

	it("compares only the overlapping prefix of unequal-length vectors", () => {
		expect(cosine([1, 0, 99], [1, 0])).toBeCloseTo(1);
	});
});

describe("reconcile/cluster — candidate generation", () => {
	it("groups near vectors and drops singletons", () => {
		const items = [input("a"), input("b"), input("c")];
		const vectors = [
			[1, 0],
			[0.99, 0.01], // near a
			[0, 1], // far → singleton, dropped
		];
		const clusters = clusterBySimilarity(items, vectors, 0.83);
		expect(clusters).toHaveLength(1);
		expect(clusters[0]?.member_ids).toEqual(["a", "b"]);
	});

	it("never clusters across scopes even when vectors are identical", () => {
		const items = [input("a", { scope: "project" }), input("b", { scope: "profile" })];
		const vectors = [
			[1, 0],
			[1, 0],
		];
		expect(clusterBySimilarity(items, vectors, 0.83)).toHaveLength(0);
	});

	it("throws when items and vectors disagree in length", () => {
		expect(() => clusterBySimilarity([input("a")], [], 0.83)).toThrow(/items.*vectors/);
	});
});

describe("reconcile/judge — prompt + parse", () => {
	it("buildJudgePrompt lists every id and the strict-JSON shape", () => {
		const prompt = buildJudgePrompt([input("x"), input("y")]);
		expect(prompt).toContain("id=x");
		expect(prompt).toContain("id=y");
		expect(prompt).toContain('"relation": "duplicate" | "supersedes"');
	});

	it("parseJudgeOutput slices JSON out of prose and validates it", () => {
		const out = parseJudgeOutput(
			'Here is my answer:\n{ "groups": [ { "member_ids": ["a","b"], "relation": "duplicate", "canonical_id": "a", "rationale": "same" } ] }\nDone.',
		);
		expect(out.groups[0]?.relation).toBe("duplicate");
	});

	it("parseJudgeOutput defaults missing groups to empty", () => {
		expect(parseJudgeOutput("{}").groups).toEqual([]);
	});

	it("parseJudgeOutput throws on no JSON and on a bad relation", () => {
		expect(() => parseJudgeOutput("no json here")).toThrow(/no JSON/);
		expect(() =>
			parseJudgeOutput('{"groups":[{"member_ids":["a","b"],"relation":"bogus","canonical_id":"a","rationale":"r"}]}'),
		).toThrow();
	});
});

describe("reconcile/reconcileBulk", () => {
	it("folds exact-content duplicates into one merge, never a stray novel", async () => {
		const inputs = [
			input("a", { content_hash: "same", text: "dup" }),
			input("b", { content_hash: "same", text: "dup" }),
		];
		const res = await reconcileBulk(inputs, {
			embedder: fixedEmbedder({ dup: [1, 0] }),
			judge: cannedJudge({ groups: [] }),
		});
		expect(res.decisions).toEqual([
			{
				verb: "merge",
				canonical_id: "a",
				member_ids: ["a", "b"],
				basis: "exact_hash",
				rationale: "identical normalised content",
			},
		]);
		expect(res.stats.exact_dup_groups).toBe(1);
		expect(res.stats.novel).toBe(0);
	});

	it("merges a judged duplicate cluster (basis judge) and leaves distinct claims novel", async () => {
		const inputs = [input("a", { text: "ta" }), input("b", { text: "tb" }), input("c", { text: "tc" })];
		const res = await reconcileBulk(inputs, {
			embedder: fixedEmbedder({ ta: [1, 0], tb: [1, 0], tc: [0, 1] }),
			judge: cannedJudge({
				groups: [{ member_ids: ["a", "b"], relation: "duplicate", canonical_id: "a", rationale: "same fact" }],
			}),
		});
		const merge = res.decisions.find((d) => d.verb === "merge");
		expect(merge).toMatchObject({ verb: "merge", canonical_id: "a", member_ids: ["a", "b"], basis: "judge" });
		expect(res.decisions).toContainEqual({ verb: "novel", id: "c" });
		expect(res.stats).toMatchObject({ merges: 1, novel: 1, clusters_judged: 1 });
	});

	it("emits a supersede per superseded member of a judged 'supersedes' cluster", async () => {
		const inputs = [input("old", { text: "t" }), input("new", { text: "t" })];
		const res = await reconcileBulk(inputs, {
			embedder: fixedEmbedder({ t: [1, 0] }),
			judge: cannedJudge({
				groups: [{ member_ids: ["old", "new"], relation: "supersedes", canonical_id: "new", rationale: "newer date" }],
			}),
		});
		expect(res.decisions).toContainEqual({
			verb: "supersede",
			new_id: "new",
			superseded_id: "old",
			rationale: "newer date",
		});
		// The superseding claim is not separately re-emitted as novel.
		expect(res.decisions.filter((d) => d.verb === "novel")).toHaveLength(0);
		expect(res.stats.supersedes).toBe(1);
	});

	it("counts judge failures and falls members through to novel (no drop)", async () => {
		const inputs = [input("a", { text: "t" }), input("b", { text: "t" })];
		const failing: Judge = async () => {
			throw new Error("model down");
		};
		const res = await reconcileBulk(inputs, { embedder: fixedEmbedder({ t: [1, 0] }), judge: failing });
		expect(res.stats.judge_failures).toBe(1);
		expect(res.stats.clusters_judged).toBe(0);
		expect(res.decisions).toContainEqual({ verb: "novel", id: "a" });
		expect(res.decisions).toContainEqual({ verb: "novel", id: "b" });
	});

	it("ignores a group that references an unknown id or whose canonical is absent", async () => {
		const inputs = [input("a", { text: "t" }), input("b", { text: "t" })];
		const res = await reconcileBulk(inputs, {
			embedder: fixedEmbedder({ t: [1, 0] }),
			judge: cannedJudge({
				groups: [
					{ member_ids: ["a", "ghost"], relation: "duplicate", canonical_id: "a", rationale: "bad" },
					{ member_ids: ["a", "b"], relation: "duplicate", canonical_id: "zzz", rationale: "bad canonical" },
				],
			}),
		});
		// Both groups rejected → both claims remain novel.
		expect(res.decisions).toContainEqual({ verb: "novel", id: "a" });
		expect(res.decisions).toContainEqual({ verb: "novel", id: "b" });
		expect(res.stats.merges).toBe(0);
	});
});

describe("reconcile/reconcileOne — ingestion", () => {
	const deps = (over: { embedder?: Embedder; judge?: Judge } = {}) => ({
		embedder: over.embedder ?? fixedEmbedder({ cand: [1, 0] }),
		judge: over.judge ?? cannedJudge({ groups: [] }),
	});

	it("merges on an exact-hash hit without embedding or judging", async () => {
		const corpus: CorpusEntry[] = [{ input: input("e1", { content_hash: "h" }), vector: [1, 0] }];
		const cand = input("cand", { content_hash: "h" });
		const decision = await reconcileOne(cand, corpus, deps());
		expect(decision).toMatchObject({ verb: "merge", canonical_id: "e1", basis: "exact_hash" });
	});

	it("is novel when no neighbour clears the threshold", async () => {
		const corpus: CorpusEntry[] = [{ input: input("e1"), vector: [0, 1] }];
		const cand = input("cand", { text: "cand" });
		expect(await reconcileOne(cand, corpus, deps())).toEqual({ verb: "novel", id: "cand" });
	});

	it("ignores neighbours in a different scope", async () => {
		const corpus: CorpusEntry[] = [{ input: input("e1", { scope: "profile" }), vector: [1, 0] }];
		const cand = input("cand", { text: "cand", scope: "project" });
		expect(await reconcileOne(cand, corpus, deps())).toEqual({ verb: "novel", id: "cand" });
	});

	it("merges the candidate into a near neighbour the judge confirms", async () => {
		const corpus: CorpusEntry[] = [{ input: input("e1"), vector: [1, 0] }];
		const cand = input("cand", { text: "cand" });
		const decision = await reconcileOne(
			cand,
			corpus,
			deps({
				judge: cannedJudge({
					groups: [{ member_ids: ["cand", "e1"], relation: "duplicate", canonical_id: "e1", rationale: "same" }],
				}),
			}),
		);
		expect(decision).toMatchObject({ verb: "merge", canonical_id: "e1", basis: "judge" });
	});

	it("supersedes the existing record when the candidate is the newer claim", async () => {
		const corpus: CorpusEntry[] = [{ input: input("e1"), vector: [1, 0] }];
		const cand = input("cand", { text: "cand" });
		const decision = await reconcileOne(
			cand,
			corpus,
			deps({
				judge: cannedJudge({
